const procurementStates=[['','كل الحالات'],['unassigned','غير مسندة'],['assigned','مسندة للشراء'],['collecting','قيد الجمع'],['awaiting_customer','بانتظار قرار العميل'],['shortage_approved','نقص وافق عليه العميل'],['ready','جاهزة لتسليم العهدة'],['handover_pending','بانتظار قبول المندوب'],['handed_over','بيد المندوب'],['cancelled','ملغاة']];
const procurementStateName=value=>procurementStates.find(([state])=>state===value)?.[1]||value||'غير محددة';
const procurementCount=value=>Number.isSafeInteger(Number(value))&&Number(value)>=0?number(Number(value)):'غير مسجل';
const procurementQuantity=value=>Number.isFinite(Number(value))&&Number(value)>=0?number(Number(value)):'غير مسجلة';
function procurementAdjustmentFacts(data){
 const job=data?.job||{},shortage=data?.shortage||{},total=Number(data?.customer_terms?.total_halalas),reduction=Number(shortage.proposed_reduction_halalas);
 if(!['admin','finance'].includes(state.user?.role)||data?.financial_detail_included!==true||job.state!=='shortage_approved'||shortage.state!=='approved'||shortage.decision?.decision!=='approve_removal'||!/^prc-[0-9a-f]{32}$/.test(job.id||'')||!/^shr-[0-9a-f]{32}$/.test(shortage.id||'')||!Number.isSafeInteger(Number(job.revision))||Number(job.revision)<1||!Number.isSafeInteger(total)||!Number.isSafeInteger(reduction)||reduction<1||total-reduction<1)return null;
 return {job_id:job.id,request_id:shortage.id,revision:Number(job.revision),before:total,reduction,after:total-reduction};
}
function procurementAssignmentFacts(data){
 const job=data?.job||{};
 if(state.user?.role!=='admin'||!['unassigned','assigned'].includes(job.state)||!/^prc-[0-9a-f]{32}$/.test(job.id||'')||!Number.isSafeInteger(Number(job.revision))||Number(job.revision)<1)return null;
 return {job_id:job.id,revision:Number(job.revision),assigned_to:job.assigned_to||''};
}
function procurementPurchaseFacts(data){
 const job=data?.job||{},lines=(data?.lines||[]).filter(line=>Number(line.remaining_qty)>0);
 if(!['admin','picker'].includes(state.user?.role)||job.assigned_to!==state.user?.id||!['assigned','collecting'].includes(job.state)||!/^prc-[0-9a-f]{32}$/.test(job.id||'')||!Number.isSafeInteger(Number(job.revision))||Number(job.revision)<1||!lines.length)return null;
 return {job_id:job.id,revision:Number(job.revision),lines};
}
function procurementFundingFacts(data){
 const job=data?.job||{},funded=new Set((data?.funding||[]).map(entry=>entry.purchase_record_id)),purchases=(data?.purchases||[]).filter(record=>!funded.has(record.id)&&/^pur-[0-9a-f]{32}$/.test(record.id||'')&&Number.isSafeInteger(Number(record.total_actual_cost_halalas))&&Number(record.total_actual_cost_halalas)>=0);
 if(!['admin','finance'].includes(state.user?.role)||data?.financial_detail_included!==true||!/^prc-[0-9a-f]{32}$/.test(job.id||'')||!purchases.length)return null;
 return {job_id:job.id,purchases};
}
function procurementSettlementFacts(data){
 const job=data?.job||{},funding=(data?.funding||[]).filter(entry=>['employee_paid','supplier_credit'].includes(entry.funding_source)&&/^pfd-[0-9a-f]{32}$/.test(entry.id||'')&&Number.isSafeInteger(Number(entry.outstanding_halalas))&&Number(entry.outstanding_halalas)>0);
 if(!['admin','finance'].includes(state.user?.role)||data?.financial_detail_included!==true||!/^prc-[0-9a-f]{32}$/.test(job.id||'')||!funding.length)return null;
 return {job_id:job.id,funding};
}
function procurementQuantityInput(value,max){
 const text=String(value??'').trim().replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).replace('٫','.');
 if(!/^\d+(\.\d{1,3})?$/.test(text))throw Error('أدخل كمية موجبة بحد أقصى ثلاث منازل عشرية');
 const quantity=Number(text);if(!Number.isFinite(quantity)||quantity<=0||quantity>Number(max))throw Error('الكمية تتجاوز المتبقي المطلوب من العميل');return quantity;
}
async function procurementPickupChoices(){
 const rows=[];let after=null;
 for(let page=0;page<10;page++){
  const data=await get('/api/ops/pickup-sites?limit=100'+(after?'&after_id='+encodeURIComponent(after):''));rows.push(...(data.items||[]));after=data.next||null;if(!after)return rows.filter(site=>site.active&&site.supplier_active);
 }
 throw Error('دليل الموردين كبير جدًا لهذه الشاشة؛ استخدم مرشحًا أو قسّم الدليل قبل تسجيل الشراء');
}
async function procurementAssignmentDialog(data){
 const facts=procurementAssignmentFacts(data);if(!facts)return;
 const roster=(await get('/api/ops/staff')).items||[],staff=roster.filter(user=>user.active&&['admin','picker'].includes(user.role)&&user.id!==facts.assigned_to);
 if(!staff.length)throw Error('لا يوجد موظف شراء أو مدير نشط يمكن تكليفه');
 const d=modal('تكليف موظف الشراء',`<form id="procurement-assignment-form" class="stack">${selectField('employee_id','موظف الشراء',staff.map(user=>[user.id,user.name+' — '+staffRoleName(user.role)]),facts.assigned_to)}${field('reason','سبب التكليف أو إعادة الإسناد')}<p class="notice">يحدد هذا التكليف عهدة جمع الطلب فقط. لا ينشئ مخزونًا ولا يغيّر سعر العميل أو يسجل دفعًا.</p><button type="submit" class="btn primary">مراجعة التكليف وحفظه</button></form>`);
 $('#procurement-assignment-form',d).onsubmit=e=>{e.preventDefault();busy($('button[type="submit"]',e.target),async()=>{const input=formData(e.target),reason=String(input.reason||'').trim(),employee=staff.find(user=>user.id===input.employee_id);if(!employee||reason.length<3||reason.length>1000)throw Error('اختر موظفًا نشطًا وأدخل سببًا واضحًا');if(!confirm(`تكليف ${employee.name} بجمع احتياجات هذا الطلب من الموردين؟`))return;await post('/api/ops/procurement/'+encodeURIComponent(facts.job_id)+'/assignment',{employee_id:employee.id,expected_revision:facts.revision,reason});closeModal();toast('تم تكليف موظف الشراء وتوثيق السبب');await procurementPage()}).catch(()=>{})};
}
async function procurementPurchaseDialog(data){
 const facts=procurementPurchaseFacts(data);if(!facts)return;
 const sites=await procurementPickupChoices();if(!sites.length)throw Error('لا توجد نقطة استلام نشطة. راجع دليل الموردين دون إنشاء مخزن أو رصيد وهمي');
 const lineInputs=facts.lines.map((line,index)=>`<fieldset class="panel stack" data-procurement-purchase-line="${index}"><legend>${esc(line.name||line.title||'صنف')}</legend><p>المتبقي ${procurementQuantity(line.remaining_qty)}</p>${field('quantity_'+index,'الكمية المجمعة في هذه الزيارة',{type:'number',min:'0.001',max:Number(line.remaining_qty),step:'0.001',required:false})}${field('cost_'+index,'تكلفتها الفعلية لدى المورد بالريال',{placeholder:'مثال: 12.50',required:false})}${field('quality_'+index,'ملاحظة الجودة والقبول',{placeholder:'حالة الصنف عند الاستلام',required:false})}</fieldset>`).join('');
 const d=modal('تسجيل زيارة شراء',`<form id="procurement-purchase-form" class="stack">${selectField('pickup_site_id','المورد / نقطة الاستلام',sites.map(site=>[site.id,[site.supplier_name,site.name,site.city].filter(Boolean).join(' — ')]))}${field('document_reference','مرجع الفاتورة أو الإيصال')}${field('note','ملاحظة الزيارة')}${lineInputs}<p class="notice warning">أدخل فقط الكميات التي استلمتها فعليًا وتكلفتها الفعلية في هذه الزيارة. التكلفة ليست سعر العميل، ولا ينشئ الحفظ مخزونًا أو تسوية.</p><button type="submit" class="btn primary">مراجعة سجل الشراء وحفظه</button></form>`);
 $('#procurement-purchase-form',d).onsubmit=e=>{e.preventDefault();busy($('button[type="submit"]',e.target),async()=>{const input=formData(e.target),site=sites.find(row=>row.id===input.pickup_site_id),lines=[];if(!site)throw Error('اختر نقطة استلام نشطة');for(const [index,line] of facts.lines.entries()){const raw=String(input['quantity_'+index]||'').trim(),rawCost=String(input['cost_'+index]||'').trim(),quality=String(input['quality_'+index]||'').trim();if(!raw){if(rawCost||quality)throw Error('أدخل كمية الصنف أو امسح تكلفة وملاحظة هذا السطر');continue}const collected_qty=procurementQuantityInput(raw,line.remaining_qty),actual_cost_halalas=parseMoney(rawCost);if(actual_cost_halalas>9000000000000||quality.length<3||quality.length>1000)throw Error('راجع التكلفة الفعلية وملاحظة الجودة لكل صنف');lines.push({line_id:line.line_id,collected_qty,actual_cost_halalas,quality_note:quality})}if(!lines.length)throw Error('سجّل صنفًا واحدًا على الأقل استلمته فعليًا');const document_reference=String(input.document_reference||'').trim(),note=String(input.note||'').trim();if(document_reference.length<3||document_reference.length>180||note.length<3||note.length>1000)throw Error('راجع مرجع المستند وملاحظة الزيارة');const total=lines.reduce((sum,line)=>sum+line.actual_cost_halalas,0);if(!Number.isSafeInteger(total)||!confirm(`حفظ ${number(lines.length)} صنف بتكلفة فعلية ${money(total)}؟\nلن يتغير سعر العميل أو المخزون، ولا تُعد هذه تسوية دفع.`))return;await post('/api/ops/procurement/'+encodeURIComponent(facts.job_id)+'/purchases',{expected_revision:facts.revision,supplier_id:site.supplier_id,pickup_site_id:site.id,document_reference,note,lines});closeModal();toast('تم حفظ زيارة الشراء والكميات والتكلفة الفعلية');await procurementPage()}).catch(()=>{})};
}
async function procurementFundingDialog(data){
 const facts=procurementFundingFacts(data);if(!facts)return;
 const sourceNames={company_paid:'دفعت الشركة',employee_paid:'دفع الموظف ويستحق التعويض',supplier_credit:'آجل على المورد'};
 const d=modal('توثيق مصدر تمويل الشراء',`<form id="procurement-funding-form" class="stack">${selectField('purchase_record_id','عملية الشراء',facts.purchases.map(record=>[record.id,[record.supplier?.name||'مورد',money(Number(record.total_actual_cost_halalas)),record.document_reference].filter(Boolean).join(' — ')]))}${selectField('funding_source','من دفع للمورد؟',[['','اختر ما حدث فعليًا'],...Object.entries(sourceNames)])}${field('evidence_reference','مرجع إثبات الدفع أو الآجل')}${field('note','ملاحظة التمويل')}<label class="row"><input type="checkbox" name="confirmed" required>أؤكد أن المصدر المختار يطابق ما حدث فعليًا.</label><p class="notice warning">يسجل هذا الإجراء مصدر تمويل التكلفة الفعلية فقط. لا يغيّر سعر العميل أو المخزون أو التحصيل، ولا يفترض موعد سداد.</p><button type="submit" class="btn primary">مراجعة مصدر التمويل وحفظه</button></form>`);
 $('#procurement-funding-form',d).onsubmit=e=>{e.preventDefault();busy($('button[type="submit"]',e.target),async()=>{const input=formData(e.target),record=facts.purchases.find(row=>row.id===input.purchase_record_id),source=String(input.funding_source||''),evidence_reference=String(input.evidence_reference||'').trim(),note=String(input.note||'').trim();if(!record||!Object.hasOwn(sourceNames,source)||input.confirmed!=='on'||evidence_reference.length<3||evidence_reference.length>180||note.length<3||note.length>1000)throw Error('اختر عملية ومصدرًا صريحًا وأدخل مرجعًا وملاحظة');if(Number(record.total_actual_cost_halalas)===0&&source!=='company_paid')throw Error('التكلفة الصفرية لا تنشئ مستحق موظف أو مورد');if(!confirm(`توثيق أن ${sourceNames[source]} تكلفة ${money(Number(record.total_actual_cost_halalas))}؟\nلن يتغير سعر العميل أو المخزون.`))return;await post('/api/ops/procurement/'+encodeURIComponent(facts.job_id)+'/funding',{purchase_record_id:record.id,funding_source:source,evidence_reference,note});closeModal();toast('تم توثيق مصدر تمويل عملية الشراء');await procurementPage()}).catch(()=>{})};
}
async function procurementSettlementDialog(data){
 const facts=procurementSettlementFacts(data);if(!facts)return;
 const sourceName=value=>value==='employee_paid'?'تعويض الموظف':'سداد المورد';
 const d=modal('تسجيل دفعة تسوية فعلية',`<form id="procurement-settlement-form" class="stack">${selectField('funding_id','المستحق',facts.funding.map(entry=>[entry.id,sourceName(entry.funding_source)+' — متبقٍ '+money(Number(entry.outstanding_halalas))]))}${field('amount','المبلغ المدفوع فعليًا بالريال',{placeholder:'مثال: 12.50'})}${field('payment_reference','مرجع الدفع الفعلي')}${field('note','ملاحظة التسوية')}<label class="row"><input type="checkbox" name="confirmed" required>أؤكد أن هذا المبلغ دُفع فعليًا للمستفيد المحدد.</label><p class="notice warning">يمكن تسجيل سداد جزئي أو كامل حتى الرصيد المتبقي فقط. لا يغيّر هذا التحصيل من العميل أو سعره.</p><button type="submit" class="btn primary">مراجعة الدفعة وحفظها</button></form>`);
 $('#procurement-settlement-form',d).onsubmit=e=>{e.preventDefault();busy($('button[type="submit"]',e.target),async()=>{const input=formData(e.target),entry=facts.funding.find(row=>row.id===input.funding_id),amount_halalas=parseMoney(String(input.amount||'')),payment_reference=String(input.payment_reference||'').trim(),note=String(input.note||'').trim();if(!entry||input.confirmed!=='on'||!Number.isSafeInteger(amount_halalas)||amount_halalas<1||amount_halalas>Number(entry.outstanding_halalas)||payment_reference.length<3||payment_reference.length>180||note.length<3||note.length>1000)throw Error('راجع المستحق والمبلغ والمرجع والملاحظة');if(!confirm(`تسجيل ${sourceName(entry.funding_source)} بمبلغ ${money(amount_halalas)}؟\nالرصيد قبل الدفعة ${money(Number(entry.outstanding_halalas))}.`))return;await post('/api/ops/procurement/'+encodeURIComponent(facts.job_id)+'/settlements',{funding_id:entry.id,amount_halalas,payment_reference,note});closeModal();toast('تم تسجيل دفعة التسوية الفعلية');await procurementPage()}).catch(()=>{})};
}
function procurementStateBadge(value){const kind=value==='handed_over'?'success':value==='cancelled'?'danger':'neutral';return `<span class="badge ${kind}">${esc(procurementStateName(value))}</span>`}
function clearProcurementPages(){state.procurementGeneration++;state.procurementLoading=null;state.procurementItems=[];state.procurementNext=null}
function procurementCard(item){
 const financial=state.user.role!=='picker';
 return `<article class="task-card" data-procurement-job="${esc(item.id)}"><div class="row between"><h3>${esc(item.order_number||'طلب بلا رقم')}</h3>${procurementStateBadge(item.state)}</div><p>${item.assigned_name?`موظف الشراء: ${esc(item.assigned_name)}`:'لم تُسند لموظف شراء'}</p><div class="task-meta"><span>${date(item.updated_at||item.created_at)}</span><strong>${money(Number(item.customer_total_halalas))}</strong></div><p>${procurementCount(item.requested_line_count)} أصناف مطلوبة · ${procurementCount(item.purchase_count)} زيارات شراء</p><p>التكلفة الفعلية المسجلة: ${money(Number(item.actual_cost_total_halalas))}</p>${financial?`<p>مشتريات بلا مصدر تمويل: ${procurementCount(item.unfunded_purchase_count)} · مستحق موظف: ${money(Number(item.employee_reimbursement_outstanding_halalas))} · مستحق مورد: ${money(Number(item.supplier_payable_outstanding_halalas))}</p>`:''}<div class="ops-actions"><button class="btn outline" data-action="procurement-detail" data-id="${esc(item.id)}">عرض سجل الشراء</button></div></article>`;
}
async function procurementPage(more=false){
 if(!state.user||state.page!=='procurement'||(more&&(!state.procurementNext||state.procurementLoading!==null)))return;
 const user=state.user,generation=++state.procurementGeneration,query=new URLSearchParams({limit:'50'});
 if(state.procurementFilter)query.set('state',state.procurementFilter);
 if(more)for(const [key,value] of Object.entries(state.procurementNext))query.set(key,String(value));
 state.procurementLoading=generation;
 try{
  const data=await get('/api/ops/procurement?'+query);
  if(state.user!==user||state.page!=='procurement'||state.procurementGeneration!==generation)return;
  state.procurementItems=Array.from(new Map([...(more?state.procurementItems:[]),...(data.items||[])].map(item=>[item.id,item])).values());
  state.procurementNext=data.next||null;
	  const capability=state.user.role==='picker'?'يسجل موظف الشراء المسند الكميات والتكلفة الفعلية لكل زيارة مورد.':state.user.role==='admin'?'تكلّف الإدارة موظف الشراء وتوثق التمويل والتسوية، ويمكن للموظف المسند تسجيل كل زيارة فعلية.':'تتابع المالية الطلب وتوثق مصدر التمويل ودفعات التسوية الفعلية.';
	  shell(`<section class="panel stack"><h2>مهام شراء الطلبات من الموردين والمحلات</h2><p class="notice">${capability} لا ينشئ المسار مخزونًا، ولا يغيّر سعر العميل من تكلفة المورد، ولا يفترض مصدر دفع أو توقيت سداد.</p><div id="procurement-filter">${selectField('procurement_state','تصفية حسب الحالة',procurementStates,state.procurementFilter,{required:false})}</div><p role="status">المعروض: ${number(state.procurementItems.length)} مهمة${state.procurementNext?' · توجد مهام أقدم':''}</p></section><section class="task-grid ops-section">${state.procurementItems.map(procurementCard).join('')||empty('لا توجد مهام شراء','تظهر هنا المهام الحقيقية بعد تأكيد طلب بلا حجز مخزون وإسناده للموظف.')}</section>${state.procurementNext?'<button class="btn outline" data-action="procurement-more">عرض مهام أقدم</button>':''}`);
  const filter=$('[name="procurement_state"]');if(filter)filter.onchange=()=>{state.procurementFilter=filter.value;clearProcurementPages();procurementPage().catch(error=>toast(error.message,true))};
 }catch(error){
  if(state.user!==user||state.page!=='procurement'||state.procurementGeneration!==generation)return;
  if(error.code==='AUTH_REQUIRED'){state.user=null;clearProcurementPages();login()}
  throw error;
 }finally{if(state.procurementLoading===generation)state.procurementLoading=null}
}
async function procurementDetail(id){
 const user=state.user,data=await get('/api/ops/procurement/'+encodeURIComponent(id));
 if(state.user!==user||state.page!=='procurement')return;
 const job=data.job||{},lines=data.lines||[],purchases=data.purchases||[],funding=data.funding||[],settlements=data.settlements||[],shortage=data.shortage,handover=data.handover;
 const lineRows=lines.map(line=>`<div class="component-row"><span><strong>${esc(line.name||line.title||'صنف')}</strong>${line.size_label?' · '+esc(line.size_label):''}<small>المطلوب ${procurementQuantity(line.qty)} · جُمع ${procurementQuantity(line.collected_qty)} · المتبقي ${procurementQuantity(line.remaining_qty)}</small></span>${Number.isSafeInteger(Number(line.line_total_halalas))?`<strong>${money(Number(line.line_total_halalas))}</strong>`:''}</div>`).join('');
 const purchaseRows=purchases.map(purchase=>`<article class="panel stack"><div class="row between"><strong>${esc(purchase.supplier?.name||'مورد غير مسمى')}</strong><strong>${money(Number(purchase.total_actual_cost_halalas))}</strong></div><p>${esc([purchase.pickup_site?.name,purchase.pickup_site?.city,purchase.pickup_site?.address_line].filter(Boolean).join(' — ')||'موقع الاستلام محفوظ')}</p><p>مرجع المستند: ${esc(purchase.document_reference||'غير مسجل')} · ${date(purchase.created_at)}</p>${(purchase.lines||[]).map(line=>`<div class="component-row"><span>${procurementQuantity(line.collected_qty)} من ${procurementQuantity(line.requested_qty)}<small>${esc(line.quality_note||'')}</small></span><strong>${money(Number(line.actual_cost_halalas))}</strong></div>`).join('')}</article>`).join('');
 const fundingRows=funding.map(entry=>`<div class="component-row"><span>${esc(({company_paid:'دفعت الشركة',employee_paid:'دفع الموظف',supplier_credit:'آجل المورد'})[entry.funding_source]||entry.funding_source)}<small>${esc(entry.evidence_reference||'')}</small></span><strong>${money(Number(entry.principal_halalas))} · متبقٍ ${money(Number(entry.outstanding_halalas))}</strong></div>`).join('');
 const settlementRows=data.financial_detail_included?settlements.map(entry=>`<div class="component-row"><span>${date(entry.created_at)} · ${esc(entry.payment_reference||'')}<small>${esc(entry.note||'')}</small></span><strong>${money(Number(entry.amount_halalas))}</strong></div>`).join(''):'';
	 const facts=procurementAdjustmentFacts(data);
	 const assignmentFacts=procurementAssignmentFacts(data),purchaseFacts=procurementPurchaseFacts(data),fundingFacts=procurementFundingFacts(data),settlementFacts=procurementSettlementFacts(data);
 const shortageMarkup=shortage?`<section class="panel stack"><h3>النقص وقرار العميل</h3><div class="row between">${procurementStateBadge(shortage.state)}<strong>التخفيض المقترح ${money(Number(shortage.proposed_reduction_halalas))}</strong></div><p>${esc(shortage.reason||'')}</p><p>القرار: ${esc(({approve_removal:'وافق على النقص',reject_removal:'رفض النقص'})[shortage.decision?.decision]||shortage.decision?.decision||'بانتظار العميل')}${shortage.decision?.note?' · '+esc(shortage.decision.note):''}</p></section>`:'';
 const adjustmentMarkup=facts?`<form id="procurement-adjustment-form" class="panel stack"><h3>تطبيق التخفيض الموافق عليه</h3><div class="component-row"><span>الإجمالي الحالي</span><strong>${money(facts.before)}</strong></div><div class="component-row"><span>التخفيض المعتمد</span><strong>− ${money(facts.reduction)}</strong></div><div class="component-row"><span>الإجمالي بعد التطبيق</span><strong>${money(facts.after)}</strong></div><label>سبب التطبيق في سجل التدقيق<textarea name="reason" required minlength="3" maxlength="1000"></textarea></label><label class="row"><input type="checkbox" name="confirmed" required>أؤكد مطابقة المبلغ لموافقة العميل وأن الإجراء لا يضيف رسومًا.</label><p class="notice warning">يحدّث هذا الإجراء الإجمالي الحالي مرة واحدة ويحفظ السعر الأصلي. لا يسجل دفعًا أو تسوية أو مخزونًا.</p><button type="submit" class="btn primary">مراجعة التخفيض وتطبيقه</button></form>`:'';
 const handoverMarkup=handover?`<section class="panel stack"><h3>عهدة التوصيل</h3><p>${handover.accepted_at?'قبل المندوب العهدة في '+date(handover.accepted_at):'بانتظار قبول المندوب المحدد للعهدة'}.</p></section>`:'';
	 const actionMarkup=assignmentFacts||purchaseFacts?`<section class="panel stack"><h3>إجراءات الجمع</h3><div class="ops-actions">${assignmentFacts?'<button id="procurement-assignment-open" class="btn outline">تكليف موظف الشراء</button>':''}${purchaseFacts?'<button id="procurement-purchase-open" class="btn primary">تسجيل زيارة شراء</button>':''}</div><p class="notice">التكليف وسجل الشراء موثقان بالمراجعة ومنع التكرار.</p></section>`:'';
	 const financeActionMarkup=fundingFacts||settlementFacts?`<section class="panel stack"><h3>إجراءات التمويل والتسوية</h3><div class="ops-actions">${fundingFacts?'<button id="procurement-funding-open" class="btn primary">توثيق مصدر التمويل</button>':''}${settlementFacts?'<button id="procurement-settlement-open" class="btn outline">تسجيل دفعة تسوية</button>':''}</div><p class="notice">كل إجراء يحتاج إثباتًا وتأكيدًا صريحًا؛ لا يوجد مصدر دفع أو توقيت سداد افتراضي.</p></section>`:'';
	 const d=modal('سجل شراء '+(job.order_number||''),`<div class="stack"><div class="row between">${procurementStateBadge(job.state)}<span>المراجعة ${procurementCount(job.revision)}</span></div><p>موظف الشراء: ${esc(job.assigned_name||'غير مسند')} · آخر تحديث ${date(job.updated_at||job.created_at)}</p>${actionMarkup}${financeActionMarkup}<section class="panel stack"><h3>الأصناف والكميات</h3>${lineRows||'<p>لا توجد أصناف مسجلة.</p>'}<div class="row between"><strong>إجمالي العميل الحالي</strong><strong>${money(Number(data.customer_terms?.total_halalas))}</strong></div><p class="notice">بيانات اتصال العميل غير معروضة هنا، والسعر الأصلي محفوظ ولا يُعاد احتسابه من تكلفة المورد.</p></section><section class="stack"><h3>زيارات الموردين ومستندات الشراء</h3>${purchaseRows||'<p class="panel">لم تُسجل زيارة شراء.</p>'}</section><section class="panel stack"><h3>مصدر تمويل المشتريات</h3>${fundingRows||'<p>لم يُسجل مصدر تمويل.</p>'}</section>${data.financial_detail_included?`<section class="panel stack"><h3>دفعات التسوية</h3>${settlementRows||'<p>لا توجد دفعات تسوية.</p>'}</section>`:'<p class="notice">تفاصيل دفع التسويات محجوبة عن موظف الشراء وتظهر للمالية والإدارة فقط.</p>'}${shortageMarkup}${adjustmentMarkup}${handoverMarkup}<p class="notice">التكلفة والتسوية منفصلتان عن سعر العميل والمخزون والتحصيل.</p></div>`);
	 const assignmentButton=$('#procurement-assignment-open',d);if(assignmentButton)assignmentButton.onclick=()=>busy(assignmentButton,()=>procurementAssignmentDialog(data)).catch(()=>{});
	 const purchaseButton=$('#procurement-purchase-open',d);if(purchaseButton)purchaseButton.onclick=()=>busy(purchaseButton,()=>procurementPurchaseDialog(data)).catch(()=>{});
	 const fundingButton=$('#procurement-funding-open',d);if(fundingButton)fundingButton.onclick=()=>busy(fundingButton,()=>procurementFundingDialog(data)).catch(()=>{});
	 const settlementButton=$('#procurement-settlement-open',d);if(settlementButton)settlementButton.onclick=()=>busy(settlementButton,()=>procurementSettlementDialog(data)).catch(()=>{});
 const form=$('#procurement-adjustment-form',d);if(form)form.onsubmit=e=>{e.preventDefault();busy($('button[type="submit"]',form),async()=>{const input=formData(form),reason=String(input.reason||'').trim();if(input.confirmed!=='on'||reason.length<3||reason.length>1000)throw Error('أكد المطابقة وأدخل سببًا واضحًا');if(!confirm(`تطبيق التخفيض الذي وافق عليه العميل؟\nالإجمالي: ${money(facts.before)} ← ${money(facts.after)}\nالتخفيض: ${money(facts.reduction)}\nلا يضيف هذا الإجراء رسومًا ولا يغير السعر الأصلي.`))return;await post('/api/ops/procurement/'+encodeURIComponent(facts.job_id)+'/shortage-adjustment',{request_id:facts.request_id,expected_revision:facts.revision,reason});closeModal();toast('طُبق التخفيض المعتمد وأصبحت المهمة جاهزة للعهدة');await procurementPage()}).catch(()=>{})};
}

// Direct supplier collection is independent of legacy warehouse balances.
async function pickupSitesPage(more=false){
 const user=state.user,generation=(state.pickupGeneration||0)+1;state.pickupGeneration=generation;
 const after=more?state.pickupNext:null;
 const data=await get('/api/ops/pickup-sites?limit=50'+(after?'&after_id='+encodeURIComponent(after):''));
 if(state.user!==user||state.page!=='pickup-sites'||state.pickupGeneration!==generation)return;
 state.pickupItems=more?[...new Map([...(state.pickupItems||[]),...(data.items||[])].map(x=>[x.id,x])).values()]:data.items||[];
 state.pickupNext=data.next;state.pickupSuppliers=data.suppliers||[];state.pickupCanManage=data.can_manage===true;
 shell(`<section class="panel stack"><h2>الموردون والمحلات — نقاط الاستلام</h2><p class="notice">جنى بدون مستودعات: الموظف يجمع احتياجات الطلب من الموردين والمحلات. هذا دليل مواقع فقط؛ لا يؤكد توفر الأصناف ولا يسجل شراءً أو استلام بضاعة أو مبلغًا. تحويل رحلة الطلب قيد التنفيذ، ولا تفتح الطلبات اعتمادًا على الدليل.</p>${state.pickupCanManage?'<div class="row wrap"><button class="btn primary" id="new-pickup-site">+ نقطة استلام</button><button class="btn outline" id="pickup-new-supplier">+ مورد / محل</button></div>':''}${data.suppliers_truncated?'<p class="notice">الاختيار يعرض أول 250 موردًا. لا تنشئ موردًا مكررًا إن لم يظهر المطلوب.</p>':''}</section><section class="stack ops-section">${state.pickupItems.map(x=>{
 const available=x.active&&x.supplier_active,links=available?orderLinks({...x,recipient_phone:x.supplier_phone}):{};
 return `<article class="panel stack" data-pickup-site="${esc(x.id)}"><h3>${esc(x.name)}</h3><p>${esc(x.supplier_name)} · ${available?'نقطة استلام نشطة':x.active?'المورد متوقف':'مسودة / متوقفة'}</p><p>${esc([x.city,x.address_line].filter(Boolean).join(' — ')||'العنوان لم يكتمل')}</p><p>${esc(x.instructions||'')}</p><div class="row wrap">${links.directions?`<a class="btn outline" data-pickup-directions href="${esc(links.directions)}" target="_blank" rel="noopener noreferrer">الملاحة إلى المورد</a>`:''}${links.phone?`<a class="btn outline" data-pickup-phone href="${esc(links.phone)}">الاتصال بالمورد</a>`:''}${state.pickupCanManage?`<button class="btn outline" data-edit-pickup="${esc(x.id)}">مراجعة النقطة</button>`:''}</div></article>`;
 }).join('')||'<p class="panel">لا توجد نقاط استلام متاحة. يُدخل المسؤول بيانات الموردين الحقيقية؛ لا يلزم إنشاء مستودع.</p>'}</section>${state.pickupNext?'<button class="btn outline" id="pickup-more">تحميل المزيد</button>':''}`);
 if(state.pickupCanManage){$('#new-pickup-site').onclick=()=>pickupSiteDialog();$('#pickup-new-supplier').onclick=()=>pickupSupplierDialog();$$('[data-edit-pickup]').forEach(b=>b.onclick=()=>pickupSiteDialog(b.dataset.editPickup))}
 const moreButton=$('#pickup-more');if(moreButton)moreButton.onclick=()=>busy(moreButton,()=>pickupSitesPage(true)).catch(()=>{});
}
function pickupSupplierDialog(){
 const d=modal('مورد / محل جديد',`<form id="pickup-supplier-form" class="stack">${field('name','اسم المورد أو المحل')}${field('phone','رقم التواصل',{required:false})}<p class="notice">تعريف مورد فقط؛ لا يسجل مشتريات أو مخزونًا. راجع الموردين الموجودين لتجنب التكرار.</p><button class="btn primary" type="submit">حفظ المورد</button></form>`);
 $('#pickup-supplier-form',d).onsubmit=e=>{e.preventDefault();busy($('button[type=submit]',e.target),async()=>{await post('/api/ops/suppliers',formData(e.target));state.catalog=null;closeModal();await pickupSitesPage()}).catch(()=>{})};
}
function pickupCoordinate(value){
 const text=String(value??'').trim();if(text==='')return null;
 const normalized=text.replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).replace('٫','.');
 if(!/^-?\d+(\.\d+)?$/.test(normalized)||!Number.isFinite(Number(normalized)))throw Error('أدخل الإحداثيات كأرقام عشرية');
 return Number(normalized);
}
function pickupSiteDialog(id=null){
 if(!state.pickupCanManage)return;
 const current=(state.pickupItems||[]).find(x=>x.id===id);if(id&&!current)return;
 const suppliers=state.pickupSuppliers||[];if(!id&&!suppliers.length){toast('أضف المورد أو المحل الحقيقي أولًا',true);return}
 const d=modal(current?'مراجعة نقطة الاستلام':'نقطة استلام لدى المورد',`<form id="pickup-site-form" class="stack">${current?`<p>المورد: ${esc(current.supplier_name)}</p>`:selectField('supplier_id','المورد / المحل',suppliers.map(x=>[x.id,x.name+(x.active?'':' — متوقف')]))}${field('name','اسم نقطة الاستلام',{value:current?.name||''})}${field('city','المدينة',{value:current?.city||'',required:false})}${field('address_line','عنوان المحل / نقطة الاستلام',{value:current?.address_line||'',required:false})}${field('latitude','خط العرض',{value:current?.latitude??'',required:false})}${field('longitude','خط الطول',{value:current?.longitude??'',required:false})}${field('instructions','تعليمات الاستلام (اختياري)',{value:current?.instructions||'',required:false})}${selectField('active','حالة الموقع',[['false','مسودة / متوقف'],['true','نشط بعد مراجعة العنوان']],String(current?.active===true))}${field('reason','سبب الحفظ أو التعديل')}<p class="notice">التفعيل يحتاج مدينة وعنوانًا وإحداثيات صحيحة وموردًا نشطًا. لا تنشئ مخزنًا أو كمية تقديرية. تغيير هذه البيانات لا يغيّر الطلبات أو الأسعار أو الأرصدة.</p><button class="btn primary" type="submit">حفظ نقطة الاستلام</button></form>`);
 $('#pickup-site-form',d).onsubmit=e=>{e.preventDefault();const form=e.target;busy($('button[type=submit]',form),async()=>{
  const x=formData(form),changes={name:x.name,city:x.city,address_line:x.address_line,latitude:pickupCoordinate(x.latitude),longitude:pickupCoordinate(x.longitude),instructions:x.instructions,active:x.active==='true',...(!current?{supplier_id:x.supplier_id}:{})};
  if((changes.latitude===null)!==(changes.longitude===null)||(changes.latitude!==null&&(Math.abs(changes.latitude)>90||Math.abs(changes.longitude)>180)))throw Error('راجع خط العرض وخط الطول معًا');
  const user=state.user;await (current?patch:post)('/api/ops/pickup-sites'+(current?'/'+current.id:''),{...changes,revision:current?.revision??null,reason:x.reason});
  closeModal();toast('تم حفظ نقطة الاستلام دون تغيير المخزون أو الأموال');if(state.user===user&&state.page==='pickup-sites')await pickupSitesPage();
 }).catch(()=>{})};
}

// Atomic owner-file import. Validation happens in the browser and again inside one
// database transaction. Imported products remain drafts until individually reviewed.
function importStockMaster(){
 const d=modal('استيراد تعريفات المخزون',`<div class="stack"><p>أدخل أسماء الأصناف ووحداتها وحدود إعادة الطلب فقط. لا يتضمن الملف كميات أو تكاليف أو موردين؛ كل تعريف جديد يبدأ متوقفًا وبرصيد صفري حتى تراجعه وتفعّله وتستلم بضاعة فعلية.</p><div class="row wrap"><button class="btn outline" type="button" data-download-stock-csv>تنزيل نموذج Excel/CSV</button><button class="btn outline" type="button" data-download-stock-json>تنزيل نموذج JSON</button><label class="btn outline">اختيار CSV أو JSON<input type="file" accept="text/csv,.csv,application/json,.json" data-stock-file hidden></label></div><div data-stock-preview class="notice">لم يُختر ملف بعد.</div><label class="row"><input type="checkbox" data-confirm-stock disabled> راجعت الأسماء والوحدات، وأريد إنشاء تعريفات متوقفة بأرصدة صفرية.</label><button class="btn primary" type="button" data-submit-stock disabled>إنشاء التعريفات دفعة واحدة</button></div>`);
 let payload=null;const preview=$('[data-stock-preview]',d),confirmBox=$('[data-confirm-stock]',d),submit=$('[data-submit-stock]',d);
 $('[data-download-stock-json]',d).onclick=()=>downloadJSON('jana-stock-master-template.json',stockImportTemplate());
 $('[data-download-stock-csv]',d).onclick=()=>downloadText('jana-stock-master-template.csv',stockImportCsvTemplate(),'text/csv;charset=utf-8');
 $('[data-stock-file]',d).onchange=async e=>{payload=null;confirmBox.checked=false;confirmBox.disabled=true;submit.disabled=true;try{const file=e.target.files?.[0];if(!file)throw Error('اختر ملف CSV أو JSON');if(file.size>300000)throw Error('حجم الملف يتجاوز 300 كيلوبايت');const text=await file.text(),checked=file.name.toLowerCase().endsWith('.csv')||file.type==='text/csv'?stockImportFromCsv(text):validateStockImport(JSON.parse(text));payload={schema_version:checked.schema_version,items:checked.items};preview.className='notice success';preview.innerHTML=`جاهز للمراجعة: <strong>${number(checked.summary.items)}</strong> تعريف مخزون؛ ${number(checked.summary.gram)} بالجرام و${number(checked.summary.piece)} بالقطعة. لا يحتوي الملف أي كمية أو تكلفة.`;confirmBox.disabled=false}catch(error){preview.className='notice warning';preview.textContent=error instanceof SyntaxError?'ملف JSON غير صالح':error.message}}
 confirmBox.onchange=()=>{submit.disabled=!payload||!confirmBox.checked};
 submit.onclick=()=>busy(submit,async()=>{if(!payload||!confirmBox.checked)throw Error('راجع الملف وأكد إنشاء التعريفات المتوقفة');const result=await post('/api/ops/stock/import',payload);state.catalog=null;closeModal();toast(`أُنشئ ${number(result.imported_count)} تعريف مخزون متوقف وبرصيد صفري. راجعها قبل التفعيل والاستلام.`);await inventoryPage()}).catch(()=>{});
}

function importCatalogDrafts(){
 const stock=(state.catalog?.stock||[]).filter(x=>x.active);if(!stock.length){toast('أضف أصناف المخزون أولًا ثم حمّل نموذج الكتالوج',true);return}
 const d=modal('استيراد مسودات الكتالوج',`<div class="stack"><p>استخدم CSV مع Excel لإدخال الأسعار بالريال، أو JSON لإدخالها بالهللة. صف CSV يمثل مكوّنًا واحدًا، ويمكن للحجم أن يتكرر عند تعدد مكوناته. الملف لا يفعّل البيع ولا يغير المخزون.</p><div class="row wrap"><button class="btn outline" type="button" data-download-catalog-csv>تنزيل نموذج Excel/CSV</button><button class="btn outline" type="button" data-download-catalog>تنزيل نموذج JSON</button><label class="btn outline">اختيار CSV أو JSON<input type="file" accept="text/csv,.csv,application/json,.json" data-catalog-file hidden></label></div><div data-catalog-preview class="notice">لم يُختر ملف بعد.</div><label class="row"><input type="checkbox" data-confirm-catalog disabled> راجعت أسماء المنتجات والأسعار والمكونات، وأريد إنشاءها كمسودات فقط.</label><button class="btn primary" type="button" data-submit-catalog disabled>إنشاء المسودات دفعة واحدة</button></div>`);
 let payload=null;const preview=$('[data-catalog-preview]',d),confirmBox=$('[data-confirm-catalog]',d),submit=$('[data-submit-catalog]',d);
 $('[data-download-catalog]',d).onclick=()=>downloadJSON('jana-catalog-template.json',catalogImportTemplate(stock));
 $('[data-download-catalog-csv]',d).onclick=()=>downloadText('jana-catalog-template.csv',catalogImportCsvTemplate(stock),'text/csv;charset=utf-8');
 $('[data-catalog-file]',d).onchange=async e=>{payload=null;confirmBox.checked=false;confirmBox.disabled=true;submit.disabled=true;try{const file=e.target.files?.[0];if(!file)throw Error('اختر ملف CSV أو JSON');if(file.size>1000000)throw Error('حجم الملف يتجاوز 1 ميجابايت');const text=await file.text(),checked=file.name.toLowerCase().endsWith('.csv')||file.type==='text/csv'?catalogImportFromCsv(text,stock):validateCatalogImport(JSON.parse(text),stock);payload={schema_version:checked.schema_version,products:checked.products};preview.className='notice success';preview.innerHTML=`جاهز للمراجعة: <strong>${number(checked.summary.products)}</strong> منتج، <strong>${number(checked.summary.offerings)}</strong> حجم بيع، <strong>${number(checked.summary.components)}</strong> مكوّن. ستنشأ جميعها كمسودات غير مفعلة.`;confirmBox.disabled=false}catch(error){preview.className='notice warning';preview.textContent=error instanceof SyntaxError?'ملف JSON غير صالح':error.message}}
 confirmBox.onchange=()=>{submit.disabled=!payload||!confirmBox.checked};
 submit.onclick=()=>busy(submit,async()=>{if(!payload||!confirmBox.checked)throw Error('راجع الملف وأكد إنشاء المسودات');const result=await post('/api/ops/products/import',payload);state.catalog=null;closeModal();toast(`أُنشئت ${number(result.imported_count)} مسودة. راجع كل إصدار قبل تفعيله.`);await catalogPage()}).catch(()=>{});
}
// Product version editor. Saving creates an immutable draft; activation is separate.
function newProductVersion(familyId='',copyId=''){
 const c=state.catalog||{};const source=(c.product_versions||[]).find(v=>v.id===copyId);
 if(copyId&&!source){toast('الإصدار غير موجود؛ حدّث القائمة',true);return}
 const stock=(c.stock||[]).filter(s=>s.active);
 if(!stock.length){toast('أضف أصناف المخزون أولًا لتحديد مكونات المنتج',true);return}
 const sizeUnits=[['kg','كيلوجرام'],['piece','قطعة'],['pack','عبوة'],['package','عبوة مجمعة'],['basket','سلة']];
 const componentRow=(comp={})=>`<div class="component-edit panel"><div class="row wrap">${selectField('stock_id','صنف المخزون',stock.map(s=>[s.id,s.name+' — '+(s.base_unit==='gram'?'جرام':'قطعة')]),comp.stock_id)}${field('base_qty','الكمية بوحدة الأساس',{type:'number',min:1,step:1,value:comp.base_qty??''})}${field('list_price','القيمة المرجعية للمكوّن (ر.س)',{value:((comp.list_price_halalas??0)/100).toFixed(2)})}<button class="btn danger small" type="button" data-remove-component>حذف المكوّن</button></div></div>`;
 const sizeRow=(o={})=>`<fieldset class="panel size-edit" data-size-key="${esc(o.sellable_key||'size-'+crypto.randomUUID().slice(0,8))}"><legend>حجم قابل للبيع</legend><div class="row wrap">${field('size_label','وصف الحجم',{value:o.size_label||'',placeholder:'مثل 500 جرام أو سلة صغيرة'})}${field('price','السعر بالريال',{value:o.price_halalas===undefined?'':(o.price_halalas/100).toFixed(2)})}${selectField('sale_unit','وحدة البيع',sizeUnits,o.sale_unit||'kg')}</div><div class="row wrap">${field('weight_under','أقصى نقص مسموح في الوزن (%)',{type:'number',min:0,max:100,step:'0.01',value:(o.weight_under_bps??10000)/100})}${field('weight_over','أقصى زيادة مجانية في الوزن (%)',{type:'number',min:0,max:20,step:'0.01',value:(o.weight_over_bps??0)/100})}</div><small>حدود الوزن تخص منتجًا من مكوّن واحد بالجرام. للسلال والقطع اترك النقص 100% والزيادة 0%. الزيادة لا تُفعّل إلا في إصدار جديد؛ لا يُحصّل عليها مبلغ إضافي.</small><div class="size-components stack">${(o.components?.length?o.components:[{}]).map(componentRow).join('')}</div><div class="ops-actions"><button type="button" class="btn outline small" data-add-component>+ مكوّن</button><button type="button" class="btn danger small" data-remove-size>حذف الحجم</button></div></fieldset>`;
 const initial=source?(c.offerings||[]).filter(o=>o.product_version_id===source.id):[{}];
 const d=modal(source?'نسخ إصدار المنتج':'عائلة منتج جديدة',`<form id="product-version-form" class="stack">${field('title','اسم المنتج',{value:source?.title||''})}${selectField('kind','نوع المنتج',[['individual','منتج فردي'],['sized','أحجام متعددة'],['basket','سلة'],['usage','حسب الاستخدام'],['bulk','جملة'],['gift','هدية']],source?.kind||'sized')}${selectField('category','القسم',[['fruit','فواكه'],['vegetables','خضروات'],['baskets','سلال']],source?.category||'fruit')}<label>الوصف<textarea name="description" rows="3">${esc(source?.description||'')}</textarea></label>${field('emoji','رمز مختصر (اختياري)',{required:false,value:source?.emoji||''})}${field('image_url','رابط صورة HTTPS (اختياري)',{type:'url',required:false,value:source?.image_url||''})}<div id="sizes-editor" class="stack">${initial.map(sizeRow).join('')}</div><button class="btn outline" type="button" id="add-size">+ حجم بيع</button><p class="notice">الكميات بوحدة المخزون الأساسية: جرام أو قطعة. تُحفظ الأسماء والوحدات من سجل المخزون. الحفظ ينشئ مسودة جديدة؛ يصبح البيع متاحًا بعد مراجعتها وتفعيلها.</p><button class="btn primary" type="submit">حفظ مسودة الإصدار</button></form>`);
 const editor=$('#sizes-editor',d);
 $('#add-size',d).onclick=()=>{if($$('.size-edit',editor).length>=30){toast('الحد الأقصى 30 حجمًا',true);return}editor.insertAdjacentHTML('beforeend',sizeRow())};
 editor.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const size=b.closest('.size-edit');if(!size)return;
  if(b.hasAttribute('data-add-component')){const list=$('.size-components',size);if($$('.component-edit',list).length>=50){toast('الحد الأقصى 50 مكوّنًا',true);return}list.insertAdjacentHTML('beforeend',componentRow())}
  if(b.hasAttribute('data-remove-component')){if($$('.component-edit',size).length===1){toast('يحتاج الحجم مكوّنًا واحدًا على الأقل',true);return}b.closest('.component-edit').remove()}
  if(b.hasAttribute('data-remove-size')){if($$('.size-edit',editor).length===1){toast('يحتاج الإصدار حجم بيع واحدًا على الأقل',true);return}size.remove()}
 });
 $('#product-version-form',d).onsubmit=e=>{e.preventDefault();busy($('button[type="submit"]',e.target),async()=>{
  const x=formData(e.target);const offerings=$$('.size-edit',editor).map(size=>({sellable_key:size.dataset.sizeKey,size_label:$('[name="size_label"]',size).value,sale_unit:$('[name="sale_unit"]',size).value,price_halalas:parseMoney($('[name="price"]',size).value),weight_under_bps:parseMoney($('[name="weight_under"]',size).value),weight_over_bps:parseMoney($('[name="weight_over"]',size).value),components:$$('.component-edit',size).map(r=>({stock_id:$('[name="stock_id"]',r).value,base_qty:Number($('[name="base_qty"]',r).value),list_price_halalas:parseMoney($('[name="list_price"]',r).value)}))}));
  await post('/api/ops/products',{family_id:familyId||null,title:x.title,kind:x.kind,category:x.category,description:x.description,emoji:x.emoji,image_url:x.image_url,offerings});
  state.catalog=null;closeModal();toast('حُفظت المسودة. راجع الأحجام والأسعار ثم فعّل الإصدار.');await catalogPage();
 }).catch(()=>{})};
}

function newCountDialog(){
 const c=state.catalog||{stock:[],lots:[]},names=new Map(c.stock.map(x=>[x.id,x.name]));
 const d=modal('بدء جلسة جرد',`<form id="count-start" class="stack">${field('location','الموقع أو الرف الذي سيُعد فعليًا')}<p>اختر الدفعات المقبولة المراد عدها. تُحفظ قراءة النظام الآن؛ إذا تحركت الدفعة قبل الاعتماد، يلزم إعادة العد.</p>${c.lots.filter(l=>l.inspection_state==='accepted').map(l=>`<label class="row"><input type="checkbox" name="lot_id" value="${esc(l.id)}">${esc(names.get(l.stock_id)||l.stock_id)} · ${esc(l.id.slice(-8))} · ${date(l.expires_at,false)}</label>`).join('')}<button class="btn primary">بدء العد</button></form>`);
 $('#count-start',d).onsubmit=e=>{e.preventDefault();busy($('button',e.target),async()=>{const lot_ids=$$('input[name="lot_id"]:checked',e.target).map(x=>x.value);if(!lot_ids.length)throw Error('اختر دفعة واحدة على الأقل');const r=await post('/api/ops/counts',{location:formData(e.target).location,lot_ids});await inventoryPage();countDialog(r.id)}).catch(()=>{})};
}
function countDialog(id){
 const count=state.inventoryCounts.find(x=>x.id===id);if(!count)return;
 const names={uncounted:'لم تُعد',submitted:'بانتظار الاعتماد',approved:'معتمدة',rejected:'مرفوضة',cancelled:'ملغاة'};
 const d=modal('جرد '+count.location,`<div class="stack"><form id="count-quantities" class="stack">${(count.counts||[]).map(x=>`<section class="panel stack"><strong>${esc(x.stock_name)} · ${esc(x.lot_id.slice(-8))}</strong><p>قراءة النظام عند البدء: ${number(x.expected_base)} ${x.base_unit==='piece'?'قطعة':'جرام'}. الموجود الآن: ${number(x.current_base)}. المحجوز الآن: ${number(x.current_reserved)}.</p>${x.stale?'<p class="notice warning">تحركت الدفعة بعد بدء الجرد. ألغِ هذه القراءة وابدأ عدًا جديدًا.</p>':''}${count.state==='open'?field(x.id,'الكمية التي عددتها فعليًا',{type:'number',min:0,step:1}):`<p>العد الفعلي: ${number(x.observed_base)} · الفرق: ${number(x.observed_base-x.expected_base)} · ${esc(names[x.state]||x.state)}</p><p>${esc(x.reason)}${x.decision_reason?' — قرار الإدارة: '+esc(x.decision_reason):''}</p>`}${state.user.role==='admin'&&x.state==='submitted'?`<div class="row"><button type="button" class="btn primary" data-count-decision="${esc(x.id)}" data-approve="true" ${x.stale?'disabled':''}>اعتماد الفرق ${number(x.observed_base-x.expected_base)}</button><button type="button" class="btn danger" data-count-decision="${esc(x.id)}" data-approve="false">رفض القراءة</button></div>`:''}</section>`).join('')}${count.state==='open'?`${field('note','ملاحظة العد وسبب الفرق')}<button class="btn primary">إرسال العد للمراجعة</button>`:''}</form>${['open','submitted'].includes(count.state)?'<button class="btn outline" data-cancel-count>إلغاء الجلسة مع حفظ سجلها</button>':''}</div>`);
 $('#count-quantities',d).onsubmit=e=>{e.preventDefault();if(count.state!=='open')return;busy($('button[type="submit"],button:not([type])',e.target),async()=>{const v=formData(e.target),counts=count.counts.map(x=>({id:x.id,observed_base:Number(v[x.id])}));if(counts.some(x=>!Number.isSafeInteger(x.observed_base)||x.observed_base<0))throw Error('أدخل كميات صحيحة بوحدة المخزون');await post(`/api/ops/counts/${id}/submit`,{counts,note:v.note});await inventoryPage();countDialog(id)}).catch(()=>{})};
 $$('[data-count-decision]',d).forEach(b=>b.onclick=()=>busy(b,async()=>{const approve=b.dataset.approve==='true',reason=prompt(approve?'سبب اعتماد قراءة الجرد:':'سبب رفض قراءة الجرد:');if(!reason)return;const line=count.counts.find(x=>x.id===b.dataset.countDecision);if(approve&&!confirm(`اعتماد هذا العد يغير موجود الدفعة من ${line.expected_base} إلى ${line.observed_base}، ويُسجل فرق ${line.observed_base-line.expected_base}. هل تؤكد؟`))return;await post(`/api/ops/count-lines/${line.id}/decision`,{approve,reason});state.catalog=null;await inventoryPage();countDialog(id)}).catch(()=>{}));
 const cancel=$('[data-cancel-count]',d);if(cancel)cancel.onclick=()=>busy(cancel,async()=>{const reason=prompt('سبب إلغاء جلسة الجرد:');if(!reason)return;await post(`/api/ops/counts/${id}/cancel`,{reason});await inventoryPage();countDialog(id)}).catch(()=>{});
}
function stockMetadataDialog(id){
 const x=state.catalog.stock.find(x=>x.id===id);if(!x)return;
 const d=modal('إعدادات '+x.name,`<form id="stock-metadata" class="stack">${field('name','اسم الصنف',{value:x.name})}${field('name_en','الاسم بالإنجليزية (اختياري)',{value:x.name_en||'',required:false})}${field('category','التصنيف (اختياري)',{value:x.category||'',required:false})}${field('reorder_base','حد إعادة الطلب بوحدة '+(x.base_unit==='piece'?'القطعة':'الجرام')+' (اختياري)',{type:'number',min:0,value:x.reorder_base??'',required:false})}${selectField('active','الحالة',[['true','نشط'],['false','متوقف']],String(x.active))}<p>وحدة الأساس ثابتة. الحد الفارغ يعني أنه لم تُحدد سياسة إعادة الطلب لهذا الصنف.</p><button class="btn primary">حفظ الإعدادات</button></form>`);
 $('#stock-metadata',d).onsubmit=e=>{e.preventDefault();busy($('button',e.target),async()=>{const v=formData(e.target),active=v.active==='true';if(x.active&&!active&&!confirm('إيقاف الصنف يمنع حجزه للطلبات الجديدة. هل تؤكد؟'))return;const reorder_base=v.reorder_base.trim()===''?null:Number(v.reorder_base);if(reorder_base!==null&&(!Number.isSafeInteger(reorder_base)||reorder_base<0))throw Error('حد إعادة الطلب يجب أن يكون كمية صحيحة');await patch('/api/ops/stock/'+id,{name:v.name,name_en:v.name_en,category:v.category,reorder_base,active});state.catalog=null;closeModal();await inventoryPage()}).catch(()=>{})};
}
function supplierMetadataDialog(id){
 const x=state.catalog.suppliers.find(x=>x.id===id);if(!x)return;
 const d=modal('بيانات المورد',`<form id="supplier-metadata" class="stack">${field('name','اسم المورد',{value:x.name})}${field('phone','رقم التواصل',{value:x.phone||'',required:false})}${field('email','البريد الإلكتروني (اختياري)',{type:'email',value:x.email||'',required:false})}${field('notes','ملاحظات (اختياري)',{value:x.notes||'',required:false})}${selectField('active','الحالة',[['true','نشط'],['false','متوقف']],String(x.active))}<button class="btn primary">حفظ بيانات المورد</button></form>`);
 $('#supplier-metadata',d).onsubmit=e=>{e.preventDefault();busy($('button',e.target),async()=>{const v=formData(e.target),active=v.active==='true';if(x.active&&!active&&!confirm('هل تؤكد إيقاف المورد للاستلامات الجديدة؟'))return;await patch('/api/ops/suppliers/'+id,{...v,active});state.catalog=null;closeModal();await inventoryPage()}).catch(()=>{})};
}

const disposalKinds=[['waste','هدر'],['damage','تلف'],['supplier_return','إرجاع إلى المورد']];
async function disposalDialog(id){
 const lot=await get('/api/ops/lots/'+id+'/disposal');if(lot.inspection_state!=='accepted'){toast('الإجراء للدفعات المقبولة فقط',true);return}
 const unit=lot.base_unit==='piece'?'قطعة':'جرام',available=lot.on_hand_base-lot.reserved_base;
 const d=modal('إخراج مخزون — '+lot.stock_name,`<form id="disposal-form" class="stack"><p class="notice">الموجود ${number(lot.on_hand_base)} ${unit}، منه ${number(lot.reserved_base)} محجوز. أقصى كمية يمكن إخراجها الآن ${number(available)} ${unit}.</p>${selectField('kind','نوع الإجراء',disposalKinds.filter(([kind])=>kind!=='supplier_return'||lot.supplier_id),'waste')}${field('quantity_base','الكمية ('+unit+')',{type:'number',min:1,max:available})}${field('reference','مرجع مستند الإتلاف أو الإرجاع')}${field('reason','سبب الإجراء')}<p>المورد: ${esc(lot.supplier_name||'غير مسجل')}. يُخصم المخزون فعليًا وتُسجل التكلفة المتاحة. إرجاع البضاعة لا يسجل تحصيل مبلغ من المورد تلقائيًا.</p><button type="submit" class="btn danger" ${available>0?'':'disabled'}>مراجعة الإخراج وتأكيده</button></form>`);
 $('#disposal-form',d).onsubmit=e=>{e.preventDefault();busy($('button[type=submit]',e.target),async()=>{const input=formData(e.target),quantity=Number(input.quantity_base);if(!Number.isSafeInteger(quantity)||quantity<1||quantity>available)throw Error('راجع الكمية غير المحجوزة');const kind=disposalKinds.find(x=>x[0]===input.kind);if(!kind)throw Error('اختر نوع الإجراء');if(!confirm(`تأكيد ${kind[1]} لكمية ${number(quantity)} ${unit} من ${lot.stock_name}؟\nسيصبح الموجود ${number(lot.on_hand_base-quantity)} ${unit}.\nالمرجع: ${input.reference}\nهذا تسجيل إخراج فعلي من المخزون.`))return;await post('/api/ops/lots/'+id+'/disposal',{...input,quantity_base:quantity,revision:lot.quantity_revision});state.catalog=null;closeModal();toast('تم تسجيل الإخراج وحركة المخزون والتكلفة');await inventoryPage()}).catch(()=>{})};
}
async function disposalsPage(append=false){
 const cursor=append?state.disposalsNext:null;const params=cursor?'?'+new URLSearchParams(cursor):'';
 const r=await get('/api/ops/disposals'+params);state.disposals=append?[...(state.disposals||[]),...(r.items||[])]:r.items||[];state.disposalsNext=r.next;
 shell(`<section class="panel stack"><h2>سجل الهدر والتلف وإرجاع المورد</h2><p>كل إجراء مرتبط بدفعة ومستند وحركة مخزون. التكلفة المجهولة تبقى غير مسجلة، ولا يمثل الإرجاع تسوية مالية مع المورد.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ</th><th>الصنف / المورد</th><th>الإجراء</th><th>الكمية</th><th>الموجود قبل ← بعد</th><th>القيمة والتكلفة</th><th>المرجع والسبب</th><th>الموظف</th></tr></thead><tbody>${state.disposals.map(x=>`<tr><td>${date(x.created_at)}</td><td>${esc(x.stock_name)}<small>${esc(x.supplier_name||'')}</small></td><td>${esc(disposalKinds.find(k=>k[0]===x.kind)?.[1]||x.kind)}</td><td>${number(x.quantity_base)} ${x.base_unit==='piece'?'قطعة':'جرام'}</td><td>${number(x.before_on_hand)} ← ${number(x.after_on_hand)}</td><td>${x.value_halalas==null?'غير مسجلة':money(x.value_halalas)}<small>${esc(({recorded:'تكلفة مسجلة',estimated:'تكلفة تقديرية',unknown:'تكلفة مجهولة'})[x.cost_basis]||'غير محددة')}</small></td><td>${esc(x.reference)}<small>${esc(x.reason)}</small></td><td>${esc(x.actor_name)}</td></tr>`).join('')}</tbody></table></div>${state.disposals.length?'':empty('لا توجد إجراءات مسجلة','يُسجل الإخراج من صفحة المخزون بعد التحقق من الدفعة.')}${r.next?'<button class="btn outline" data-action="disposals-more">تحميل إجراءات أقدم</button>':''}</section>`);
}

function supplierCreditStatus(x){
 if(!x.credit_count)return 'بانتظار إشعار دائن';
 if(x.inventory_value_halalas==null)return 'إشعار مسجل · تكلفة المخزون مجهولة';
 if(x.variance_to_inventory_cost_halalas===0)return 'مطابق لتكلفة المخزون المرجعية';
 return x.variance_to_inventory_cost_halalas<0?'أقل من تكلفة المخزون المرجعية':'أعلى من تكلفة المخزون المرجعية';
}
async function supplierCreditsPage(append=false){
 const cursor=append?state.supplierCreditsNext:null,params=cursor?'?'+new URLSearchParams(cursor):'';
 const r=await get('/api/ops/supplier-credits'+params);if(state.page!=='supplier-credits')return;
 state.supplierCredits=append?[...(state.supplierCredits||[]),...(r.items||[])]:r.items||[];state.supplierCreditsNext=r.next;
 const canRecord=['admin','finance'].includes(state.user.role);
 shell(`<section class="panel stack"><h2>إشعارات الموردين مقابل الإرجاع</h2><p>يربط السجل إشعار المورد الدائن بإرجاع مخزون فعلي. قيمة المخزون للمقارنة فقط؛ الإشعار لا يثبت استلام نقد، ولا يغير المخزون أو تكلفة الدفعة أو حسابًا بنكيًا.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>الإرجاع / المورد</th><th>الصنف والكمية</th><th>تكلفة المخزون المرجعية</th><th>الإشعارات المسجلة</th><th>الفرق المرجعي</th><th>الحالة والإجراء</th></tr></thead><tbody>${state.supplierCredits.map(x=>`<tr data-supplier-credit="${esc(x.id)}"><td>${date(x.created_at)}<small>${esc(x.return_reference)} · ${esc(x.supplier_name)}</small></td><td>${esc(x.stock_name)}<small>${number(x.quantity_base)} ${x.base_unit==='piece'?'قطعة':'جرام'}</small></td><td>${x.inventory_value_halalas==null?'مجهولة':money(x.inventory_value_halalas)}<small>${esc(({recorded:'مسجلة',estimated:'تقديرية',unknown:'مجهولة'})[x.inventory_cost_basis]||'غير محددة')}</small></td><td>${money(x.credited_halalas)}<small>${number(x.credit_count)} مستند</small>${(x.credit_notes||[]).map(n=>`<small>${date(n.created_at)} · ${esc(n.reference)} · ${money(n.amount_halalas)} · ${esc(n.note)} · ${esc(n.actor_name)}</small>`).join('')}</td><td>${x.variance_to_inventory_cost_halalas==null?'غير قابل للحساب':money(x.variance_to_inventory_cost_halalas)}</td><td>${esc(supplierCreditStatus(x))}${canRecord?`<button class="btn outline" data-action="record-supplier-credit" data-id="${esc(x.id)}">تسجيل إشعار دائن</button>`:''}</td></tr>`).join('')}</tbody></table></div>${state.supplierCredits.length?'':empty('لا توجد إرجاعات مورد مسجلة','يظهر الإرجاع هنا بعد إخراج مخزون فعلي من دفعة مرتبطة بمورد.')}${r.next?'<button class="btn outline" data-action="supplier-credits-more">تحميل إرجاعات أقدم</button>':''}</section>`);
}
function supplierCreditDialog(id){
 const item=(state.supplierCredits||[]).find(x=>x.id===id);if(!item){toast('حدّث سجل إشعارات الموردين',true);return}
 const d=modal('إشعار دائن — '+item.supplier_name,`<form id="supplier-credit-form" class="stack"><p>إرجاع ${number(item.quantity_base)} ${item.base_unit==='piece'?'قطعة':'جرام'} من ${esc(item.stock_name)}. تكلفة المخزون المرجعية: ${item.inventory_value_halalas==null?'مجهولة':money(item.inventory_value_halalas)}. المسجل من إشعارات المورد: ${money(item.credited_halalas)}.</p>${field('amount','قيمة إشعار المورد بالريال',{placeholder:'0.00'})}${field('reference','رقم إشعار المورد الدائن')}${field('note','ملاحظة المطابقة')}<p class="notice">سجّل مستندًا استلمته فعلًا. الحفظ نهائي ومدقق، ولا يعني تحويلًا نقديًا أو قيدًا محاسبيًا بنكيًا.</p><button class="btn primary" type="submit">مراجعة الإشعار وتسجيله</button></form>`);
 $('#supplier-credit-form',d).onsubmit=e=>{e.preventDefault();busy($('button[type=submit]',e.target),async()=>{const input=formData(e.target),amount_halalas=parseMoney(input.amount);if(amount_halalas<1)throw Error('قيمة الإشعار يجب أن تكون أكبر من صفر');if(!confirm(`تأكيد تسجيل إشعار المورد ${input.reference} بقيمة ${money(amount_halalas)}؟\nهذا إثبات مستند دائن، وليس استلامًا نقديًا.`))return;await post('/api/ops/disposals/'+encodeURIComponent(id)+'/supplier-credits',{amount_halalas,reference:input.reference,note:input.note});closeModal();toast('تم تسجيل إشعار المورد وربطه بالإرجاع');await supplierCreditsPage()}).catch(()=>{})};
}

const movementKinds=[['customer_return_received','استلام مرتجع معزول'],['customer_return_accepted','قبول مرتجع للمخزون'],['customer_return_rejected','رفض مرتجع وإبقاؤه معزولًا'],['receipt_pending_inspection','استلام بانتظار الفحص'],['inspection_rejected','رفض الفحص'],['goods_receipt_accepted','اعتماد الاستلام'],['quote_reserved','حجز عرض سعر'],['quote_released','تحرير عرض سعر'],['quote_expired','انتهاء عرض سعر'],['order_reservation_release','تحرير حجز طلب'],['order_picked','استهلاك التجهيز'],['weight_reserved','حجز وزن إضافي'],['weight_reservation_release','تحرير فرق الوزن'],['substitution_reserved','حجز بديل'],['substitution_reservation_release','تحرير بديل'],['count_adjustment','تسوية مخزون'],['cycle_count_approved','اعتماد فرق الجرد'],...disposalKinds];
function movementDelta(value){return (Number(value)>0?'+':'')+number(value)}
async function movementsPage(append=false){
 const filters=state.movementFilters||{},params=new URLSearchParams(filters);if(append&&state.movementsNext)for(const[k,v]of Object.entries(state.movementsNext))params.set(k,v);
 const r=await get('/api/ops/movements'+(params.size?'?'+params:''));state.movements=append?[...(state.movements||[]),...(r.items||[])]:r.items||[];state.movementsNext=r.next;
 const localDate=ms=>ms?new Date(Number(ms)).toISOString().slice(0,10):'';
 shell(`<section class="panel stack"><p>تاريخ الحركات المسجلة. الإشارة الموجبة إضافة والسالبة خصم؛ الحجز يغيّر المحجوز دون خصم الموجود. أوقات التصفية بتوقيت السعودية. لا يُحسب رصيد تاريخي من سجل قد يسبق اكتماله إدخال المخزون.</p><form id="movement-filters" class="row wrap">${selectField('reason','نوع الحركة',[['','جميع الحركات'],...movementKinds],filters.reason||'',{required:false})}${field('reference','مرجع المستند أو الطلب',{required:false,value:filters.reference||''})}${field('from_date','من تاريخ (شامل)',{required:false,type:'date',value:localDate(filters.from_at?Number(filters.from_at)+10800000:null)})}${field('to_date','حتى تاريخ (شامل)',{required:false,type:'date',value:localDate(filters.to_at?Number(filters.to_at)-86400000+10800000:null)})}<button class="btn primary" type="submit">عرض الحركات</button><button class="btn outline" type="button" id="movements-reset">مسح التصفية</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ</th><th>الصنف / الدفعة</th><th>نوع الحركة</th><th>تغير الموجود</th><th>تغير المحجوز</th><th>أثر التكلفة</th><th>المرجع</th><th>المنفذ</th></tr></thead><tbody>${state.movements.map(x=>`<tr data-movement="${esc(x.id)}"><td>${date(x.created_at)}</td><td>${esc(x.stock_name)}<small>${esc(x.lot_id||'دون دفعة')}</small></td><td>${esc(movementKinds.find(k=>k[0]===x.reason)?.[1]||x.reason)}</td><td dir="ltr">${movementDelta(x.on_hand_delta)} ${x.base_unit==='piece'?'قطعة':'جرام'}</td><td dir="ltr">${movementDelta(x.reserved_delta)} ${x.base_unit==='piece'?'قطعة':'جرام'}</td><td>${!x.has_cost_entry?(Number(x.on_hand_delta)===0?'دون أثر على تكلفة الموجود':'لا يوجد قيد تكلفة لهذه الحركة'):x.value_delta_halalas==null?'تكلفة مجهولة':(x.value_delta_halalas>0?'+':'')+money(x.value_delta_halalas)}${x.has_cost_entry?`<small>${esc(({recorded:'مسجلة',estimated:'تقديرية',unknown:'غير مسجلة'})[x.cost_basis]||'غير محددة')}</small>`:''}</td><td>${esc(x.document_reference||x.reference)}<small>${esc(x.disposal_reason||x.return_reason||'')}</small></td><td>${esc(x.actor_name||(x.actor_id?'اسم المنفذ غير متاح':'النظام'))}</td></tr>`).join('')}</tbody></table></div>${state.movements.length?'':empty('لا توجد حركات مطابقة','راجع المرشحات أو الفترة الزمنية.')}${r.next?'<button class="btn outline" data-action="movements-more">تحميل حركات أقدم</button>':''}</section>`);
 $('#movement-filters').onsubmit=e=>{e.preventDefault();busy($('button[type="submit"]',e.target),async()=>{const input=formData(e.target),next={};for(const k of ['reason','reference'])if(input[k]?.trim())next[k]=input[k].trim();for(const[name,key]of [['from_date','from_at'],['to_date','to_at']])if(input[name]){const ms=Date.parse(input[name]+'T00:00:00+03:00')+(key==='to_at'?86400000:0);if(!Number.isSafeInteger(ms))throw Error('راجع تاريخ التصفية');next[key]=String(ms)}if(next.from_at&&next.to_at&&Number(next.from_at)>=Number(next.to_at))throw Error('تاريخ النهاية يجب ألا يسبق البداية');state.movementFilters=next;await movementsPage()}).catch(()=>{})};
 $('#movements-reset').onclick=()=>busy($('#movements-reset'),async()=>{state.movementFilters={};await movementsPage()}).catch(()=>{});
}

async function notificationJobsPage(){
 const r=await get('/api/ops/notification-jobs'),channels={email:'البريد الإلكتروني',sms:'الرسائل النصية',whatsapp:'واتساب',push:'إشعارات الأجهزة'},statuses={queued:'بانتظار الإرسال',leased:'محاولة جارية',retry:'بانتظار إعادة المحاولة',submitted:'قُبل لدى المزود',dead_letter:'توقف الإرسال',reconcile:'تحتاج مراجعة لدى المزود',cancelled:'أُلغي قبل الإرسال'};
 shell(`<section class="panel stack"><h2>حالة الإشعارات الخارجية</h2><p>قبول المزود للرسالة لا يثبت وصولها. القنوات المعطلة لا تنشئ محاولات إرسال جديدة. الحالات غير المؤكدة تحتاج تحققًا لدى المزود قبل أي إعادة إرسال.</p><div class="row wrap">${(r.channels||[]).map(x=>`<div class="panel"><strong>${esc(channels[x.channel]||x.channel)}</strong><p>${x.enabled?'مفعلة في إعدادات الطابور':'الإرسال متوقف'}</p></div>`).join('')}</div><div class="row wrap">${Object.entries(statuses).map(([k,label])=>`<span>${label}: <strong>${number(r.counts?.[k]||0)}</strong></span>`).join('')}</div><h3>آخر 50 عملية</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ</th><th>القناة</th><th>الحالة</th><th>المحاولات</th><th>رمز المراجعة</th><th>العملية</th></tr></thead><tbody>${(r.items||[]).map(x=>`<tr><td>${date(x.created_at)}</td><td>${esc(channels[x.channel]||x.channel)}</td><td>${esc(statuses[x.state]||x.state)}</td><td>${number(x.attempt_count)}</td><td>${esc(x.error_code||'—')}</td><td>${esc(x.id)}</td></tr>`).join('')}</tbody></table></div>${r.items?.length?'':empty('لا توجد محاولات إرسال خارجية','إشعارات التطبيق تحفظ بصورة مستقلة. تفعيل قناة خارجية يحتاج إعداد المزود ووجهة موثقة وموافقة مسجلة.')}</section>`);
}

async function customerReturnsPage(append=false){
 const cursor=append?state.customerReturnsNext:null,r=await get('/api/ops/customer-returns'+(cursor?'?'+new URLSearchParams(cursor):''));
 if(state.page!=='customer-returns')return;
 state.customerReturns=append?[...(state.customerReturns||[]),...r.items]:r.items;state.customerReturnsNext=r.next;
 const canInspect=['admin','inventory'].includes(state.user.role);
 shell(`<section class="panel stack"><div class="row between"><h2>مرتجعات العملاء والتوصيل</h2>${canInspect?'<button class="btn primary" data-action="new-customer-return">استلام مرتجع فعلي</button>':''}</div><p>يُربط المرتجع بالدفعة التي خرجت فعلًا في الطلب. يبقى خارج المخزون المتاح حتى اعتماد الفحص؛ المرفوض يبقى معزولًا، والاسترداد المالي إجراء مستقل.</p><div class="row wrap"><span>بانتظار الفحص: <strong>${number(r.summary.pending_receipts)}</strong></span><span>تم فحصها: <strong>${number(r.summary.inspected_receipts)}</strong></span><span>تحتوي كمية مرفوضة: <strong>${number(r.summary.rejected_receipts)}</strong></span><span>بانتظار التصرف: <strong>${number(r.summary.open_rejected_receipts||0)}</strong></span><span>أُغلق التصرف: <strong>${number(r.summary.closed_rejected_receipts||0)}</strong></span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الطلب / التاريخ</th><th>الصنف والدفعة</th><th>المستلم</th><th>نتيجة الفحص</th><th>قيمة المخزون المستعاد</th><th>المستند والسبب</th><th>الموظف والإجراء</th></tr></thead><tbody>${state.customerReturns.map(x=>{const unit=x.base_unit==='piece'?'قطعة':'جرام',i=x.inspection;return `<tr><td>${esc(x.order_number)}<small>${date(x.created_at)}</small></td><td>${esc(x.stock_name)}<small>${esc(x.lot_id)}</small></td><td>${number(x.quantity_base)} ${unit}</td><td>${i?`مقبول ${number(i.accepted_base)} ${unit}<br>مرفوض في الفحص ${number(i.rejected_base)} ${unit}<small>${esc(i.note)}</small>${i.rejected_base>0?`<small>المتبقي المعزول: ${x.disposition_summary?number(x.disposition_summary.remaining_base):'غير متاح'}</small><button class="btn outline" data-action="return-custody" data-id="${esc(x.id)}">${canInspect&&x.disposition_summary?.remaining_base>0?'سجل التصرف في المرفوض':'سجل التصرف'}</button>`:''}`:'بانتظار الفحص — غير متاح للبيع'}</td><td>${!i||!i.accepted_base?'لا إضافة للمخزون':state.user.role==='support'?'غير متاحة لهذا الدور':`${i.restored_cost_halalas==null?'غير مسجلة':money(i.restored_cost_halalas)}<small>${esc(({recorded:'من تكلفة الشحنة المسجلة',estimated:'تقديرية من تكلفة الشحنة',unknown:'تكلفة الشحنة مجهولة'})[i.cost_basis])}</small>`}</td><td>${esc(x.reference)}<small>${esc(x.reason)}</small></td><td>${esc(x.actor_name)}${i?`<small>الفحص: ${esc(i.actor_name)}</small>`:canInspect?`<button class="btn outline" data-action="inspect-customer-return" data-id="${esc(x.id)}">فحص المرتجع</button>`:''}</td></tr>`}).join('')}</tbody></table></div>${state.customerReturns.length?'':empty('لا توجد مرتجعات مسجلة','سجّل الاستلام الفعلي فقط، مع مستند وسبب.')}${r.next?'<button class="btn outline" data-action="customer-returns-more">تحميل مرتجعات أقدم</button>':''}</section>`);
}
function customerReturnLookup(){
 const d=modal('استلام مرتجع من طلب',`<form id="return-lookup" class="stack">${field('order_number','رقم الطلب')}<p>استخدم رقم طلب مسلّم أو تعذر تسليمه بعد التجهيز. تسجيل المرتجع يمنع إعادة إرسال الشحنة القديمة؛ الطلب البديل يحتاج مراجعة جديدة.</p><button type="submit" class="btn primary">عرض الدفعات المشحونة</button></form>`);
 $('#return-lookup',d).onsubmit=e=>{e.preventDefault();busy($('button',e.target),async()=>{const r=await get('/api/ops/customer-returns/context?'+new URLSearchParams({number:formData(e.target).order_number.trim()}));customerReturnReceipt(r)}).catch(()=>{})};
}
function customerReturnReceipt(context){
 const choices=context.items.filter(x=>x.returnable_base>0);
 if(!choices.length){modal('مرتجعات الطلب',empty('اكتمل استلام الكميات المشحونة','راجع سجل المرتجعات؛ لا يمكن تسجيل الكمية نفسها مرتين.'));return}
 const d=modal('استلام مرتجع — '+context.number,`<form id="customer-return-form" class="stack">${selectField('source_movement_id','الدفعة المشحونة',choices.map(x=>[x.source_movement_id,x.stock_name+' · '+(x.receipt_reference||x.lot_id)]),choices[0].source_movement_id)}<p id="return-source-info" class="notice"></p>${field('quantity_base','الكمية المستلمة فعليًا بالوحدة الموضحة',{type:'number',min:1})}${field('reference','مرجع مستند استلام المرتجع')}${field('reason','سبب الإرجاع')}<p>هذا استلام فعلي في منطقة الفحص؛ لا تزيد الكمية المتاحة للبيع ولا يُسجّل رد مبلغ للعميل.</p><button type="submit" class="btn primary">مراجعة الاستلام وتأكيده</button></form>`);
 const form=$('#customer-return-form',d),selected=()=>choices.find(x=>x.source_movement_id===form.elements.source_movement_id.value);
 function describe(){const x=selected(),unit=x.base_unit==='piece'?'قطعة':'جرام';$('#return-source-info',d).textContent=`الوحدة: ${unit}. شُحن ${number(x.shipped_base)}، سُجل إرجاع ${number(x.received_return_base)}، المتبقي الممكن إرجاعه ${number(x.returnable_base)}. الدفعة: ${x.lot_id}`;form.elements.quantity_base.max=String(x.returnable_base)}
 form.elements.source_movement_id.onchange=describe;describe();
 form.onsubmit=e=>{e.preventDefault();busy($('button[type=submit]',form),async()=>{const body=formData(form),x=selected(),quantity=Number(body.quantity_base);if(!Number.isSafeInteger(quantity)||quantity<1||quantity>x.returnable_base)throw Error('راجع الكمية المستلمة من الدفعة المختارة');if(!confirm(`هل استلم المستودع فعلًا ${number(quantity)} ${x.base_unit==='piece'?'قطعة':'جرام'} من ${x.stock_name}؟\nالمستند: ${body.reference}\nستبقى معزولة بانتظار الفحص، دون تغيير التحصيل أو الاسترداد.`))return;await post('/api/ops/customer-returns',{...body,quantity_base:quantity});closeModal();toast('سُجل المرتجع بانتظار الفحص');await customerReturnsPage()}).catch(()=>{})};
}
function customerReturnInspection(id){
 const receipt=(state.customerReturns||[]).find(x=>x.id===id);if(!receipt||receipt.inspection){toast('حدّث سجل المرتجعات',true);return}
 const unit=receipt.base_unit==='piece'?'قطعة':'جرام';
 const d=modal('فحص مرتجع — '+receipt.stock_name,`<form id="return-inspection-form" class="stack"><p>المستلم ${number(receipt.quantity_base)} ${unit}. أدخل الكمية التي اجتازت الفحص فعليًا؛ المتبقي يُسجّل مرفوضًا ومعزولًا.</p>${field('accepted_base','الكمية المقبولة ('+unit+')',{type:'number',min:0,max:receipt.quantity_base})}<label>نتيجة الفحص وسبب القبول أو الرفض<textarea name="note" required minlength="3" maxlength="1000"></textarea></label><p class="notice">اعتماد الفحص نهائي ومدقق. المقبول يعود إلى دفعته الأصلية وصلاحيتها وتكلفة الشحنة؛ لا يمكن إعادة دفعة منتهية للبيع. المرفوض لا يعود للمخزون المتاح.</p><button type="submit" class="btn primary">مراجعة الفحص واعتماده</button></form>`);
 $('#return-inspection-form',d).onsubmit=e=>{e.preventDefault();busy($('button',e.target),async()=>{const input=formData(e.target),accepted=Number(input.accepted_base);if(!Number.isSafeInteger(accepted)||accepted<0||accepted>receipt.quantity_base)throw Error('راجع نتيجة العد والفحص');if(!confirm(`اعتماد ${number(accepted)} ${unit} صالحًا وإعادة الكمية للمخزون؟\nالمرفوض والمعزول: ${number(receipt.quantity_base-accepted)} ${unit}.\nلا يُسجّل رد نقدي تلقائيًا.`))return;await post('/api/ops/customer-returns/'+id+'/inspection',{accepted_base:accepted,note:input.note});state.catalog=null;closeModal();toast('سُجل الفحص وحركة المخزون');await customerReturnsPage()}).catch(()=>{})};
}

const returnDispositionKinds=[['destroyed','إتلاف موثق'],['supplier_handover','تسليم للمورد']];
async function returnCustodyDialog(id){
 const path='/api/ops/customer-returns/'+encodeURIComponent(id)+'/dispositions';
 const result=await get(path);if(state.page!=='customer-returns')return;
 const receipt=result.receipt,unit=receipt.base_unit==='piece'?'قطعة':'جرام';
 const canWrite=['admin','inventory'].includes(state.user.role)&&receipt.inspection_complete&&receipt.remaining_base>0;
 const d=modal('التصرف في المرتجع المرفوض',`<section class="stack"><h3>${esc(receipt.stock_name)} · ${esc(receipt.order_number)}</h3><p>الدفعة: ${esc(receipt.lot_id)}</p><p class="notice">المرفوض في الفحص: ${number(receipt.rejected_base||0)} ${unit} · سُجل التصرف في: ${number(receipt.disposed_base)} ${unit} · المتبقي المعزول: <strong>${number(receipt.remaining_base||0)} ${unit}</strong></p><p>وثّق الإتلاف أو التسليم الذي نُفذ فعلًا وفق الإجراء المعتمد. التسجيل لا يمنح موافقة على التصرف، ولا يمثل رد مبلغ للعميل أو تسوية مع المورد.</p><div id="return-custody-history"></div>${canWrite?`<form id="return-disposition-form" class="stack"><h3>تسجيل تصرف فعلي</h3>${selectField('kind','التصرف المنفذ',[['','اختر الإجراء'],...returnDispositionKinds])}${field('quantity_base','الكمية التي تم التصرف فيها ('+unit+')',{type:'number',min:1,max:receipt.remaining_base,step:1})}<label>مرجع مستند التصرف<input name="reference" required maxlength="180"></label><label id="return-recipient-label" hidden>المورد والجهة المستلمة<input name="recipient" disabled minlength="3" maxlength="180"></label><label>تفاصيل الإجراء وسبب التصرف<textarea name="note" required minlength="3" maxlength="1000"></textarea></label><label class="row"><input type="checkbox" name="completed" required>أؤكد أن الإجراء نُفذ فعلًا وأن المستند يخص هذه الكمية.</label><p>تسجيل المستند نهائي ومدقق. التصرف في المعزول لا يخصم المخزون المتاح مرة أخرى.</p><button type="submit" class="btn primary">مراجعة المستند وتسجيله</button></form>`:`<p>${!receipt.inspection_complete?'يلزم اعتماد الفحص أولًا.':receipt.remaining_base===0?'لا توجد كمية مرفوضة متبقية في العهدة.':'هذه الصلاحية تتيح مراجعة السجل فقط.'}</p>`}</section>`);
 const historyRoot=$('#return-custody-history',d);let items=result.items,next=result.next;
 function drawHistory(){
  historyRoot.innerHTML=`<h3>مستندات التصرف</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>وقت التسجيل / الموظف</th><th>الإجراء والكمية</th><th>المستند والجهة</th><th>التفاصيل</th></tr></thead><tbody>${items.map(x=>`<tr data-return-disposition="${esc(x.id)}"><td>${date(x.created_at)}<small>${esc(x.actor_name)}</small></td><td>${esc(returnDispositionKinds.find(k=>k[0]===x.kind)?.[1]||x.kind)}<small>${number(x.quantity_base)} ${unit}</small></td><td>${esc(x.reference)}<small>${esc(x.recipient||'')}</small></td><td>${esc(x.note)}</td></tr>`).join('')}</tbody></table></div>${items.length?'':empty('لا توجد مستندات تصرف مسجلة','تبقى الكمية المرفوضة في العهدة حتى تسجيل التصرف الفعلي.')}${next?'<button type="button" class="btn outline" id="return-custody-more">تحميل مستندات أقدم</button>':''}`;
  if(next)$('#return-custody-more',historyRoot).onclick=e=>busy(e.currentTarget,async()=>{
   const page=await get(path+'?'+new URLSearchParams(next));
   if(!historyRoot.isConnected||!d.open)return;
   const known=new Set(items.map(x=>x.id));items.push(...page.items.filter(x=>!known.has(x.id)));next=page.next;drawHistory();
  }).catch(()=>{});
 }
 drawHistory();if(!canWrite)return;
 const form=$('#return-disposition-form',d);
 form.elements.kind.onchange=()=>{
  const handover=form.elements.kind.value==='supplier_handover';
  $('#return-recipient-label',d).hidden=!handover;
  form.elements.recipient.disabled=!handover;form.elements.recipient.required=handover;
  if(!handover)form.elements.recipient.value='';
 };
 form.onsubmit=e=>{e.preventDefault();return busy($('button[type=submit]',form),async()=>{
  const input=formData(form),quantity=Number(input.quantity_base),kind=input.kind;
  if(!String(input.quantity_base||'').trim()||!Number.isSafeInteger(quantity)||quantity<1||quantity>receipt.remaining_base)throw Error('راجع الكمية الفعلية؛ لا تتجاوز المتبقي المعزول');
  if(!returnDispositionKinds.some(x=>x[0]===kind)||!form.elements.completed.checked)throw Error('اختر التصرف وأكد تنفيذه الفعلي أولًا');
  const reference=String(input.reference||'').trim(),note=String(input.note||'').trim(),recipient=kind==='supplier_handover'?String(input.recipient||'').trim():null;
  if(!reference||reference.length>180||note.length<3||note.length>1000||(recipient!==null&&(recipient.length<3||recipient.length>180)))throw Error('أكمل المستند والتفاصيل والجهة المستلمة');
  if(!confirm(`تسجيل ${returnDispositionKinds.find(x=>x[0]===kind)[1]} لعدد ${number(quantity)} ${unit}؟\nالمستند: ${reference}${recipient?'\nالجهة: '+recipient:''}\nيبقى معزولًا بعد التسجيل: ${number(receipt.remaining_base-quantity)} ${unit}.\nالسجل نهائي؛ لا يغيّر المخزون المتاح أو الأموال.`))return;
  await post(path,{kind,quantity_base:quantity,reference,recipient,note});closeModal();toast('سُجل التصرف الفعلي في المرتجع');await customerReturnsPage();
 }).catch(()=>{})};
}

async function storefrontPage(){
 const user=state.user,generation=++state.storefrontGeneration;const data=await get('/api/ops/storefront');if(state.user!==user||state.page!=='storefront'||state.storefrontGeneration!==generation)return;state.storefrontDirty=false;const p=data.draft||{},r=data.readiness||{},opening=openingReview(data);
 const fields=[['display_name','اسم المتجر'],['legal_name','الاسم القانوني للمنشأة'],['registration_number','رقم السجل أو الوثيقة'],['business_address','عنوان المنشأة'],['phone','هاتف خدمة العملاء'],['email','بريد خدمة العملاء'],['support_hours','أيام وساعات خدمة العملاء'],['tax_number','رقم التسجيل الضريبي (للمسجل فقط)']];
 const policies=[['terms','شروط البيع'],['privacy','سياسة الخصوصية'],['delivery','سياسة التوصيل والبدائل'],['returns','سياسة الإلغاء والاسترداد']];
 const reviewed=[['catalog','راجعت أسماء المنتجات وأسعارها وصورها وأزلت بيانات المعاينة'],['inventory','طابقت المخزون الفعلي مع الأرصدة وسجلت استلامه وفحصه'],['coverage','اعتمدت مستودع الانطلاق والتغطية والمواعيد ورسوم التوصيل'],['tax','تحققت من الحالة الضريبية ومتطلبات الفوترة للمنشأة'],['operations','جهزت الموظفين والتحصيل والدعم والنسخ الاحتياطي واختبرت التشغيل']];
 shell(`<div class="stack" data-store-revision="${data.revision}"><p class="notice">تُحفظ التعديلات كمسودة. النشر ينشئ إصدارًا محفوظًا يراه العميل؛ فتح الطلبات إجراء مستقل. تظل الطلبات السابقة وعروض السعر المحجوزة قابلة للمتابعة عند الإيقاف.</p><section class="panel stack"><h2>${data.accepting_orders?'استقبال الطلبات مفتوح':'استقبال الطلبات متوقف'}</h2><p>الإصدار المنشور: ${data.published?data.published.version:'لا يوجد'} · مراجعة الإعدادات ${data.revision}</p><div class="store-readiness">${[['ملف المنشأة',r.profile_published?'منشور':'لم يُنشر'],['مستودع الانطلاق',r.warehouse_ready?'مكتمل ومرتبط':'غير مكتمل'],['منتجات المعاينة النشطة',r.preview_products],['منتجات متوفرة',r.available_products],['مواعيد متوفرة مرتبطة',r.available_slots],['سلامة الأرصدة',r.health?.ok?'الفحوصات سليمة':'تحتاج مراجعة'],['التشغيل الضريبي',r.tax_supported?'حالة غير مسجل وفق إفادة المالك':'لم تُعتمد حالة مدعومة']].map(([label,value])=>`<div><strong>${label}</strong><p>${esc(value??'غير متاح')}</p></div>`).join('')}</div><p>الفتح يدعم حاليًا المنشأة التي يقر مالكها بأنها غير مسجلة في ضريبة القيمة المضافة. المنشأة المسجلة تحتاج ربط الضرائب والفوترة قبل التشغيل.</p></section>
 <section class="panel stack" data-opening-review="${opening?data.opening_review_matches_published?'current':'historical':'none'}"><h2>آخر اعتماد مسجل لفتح الطلبات</h2>${opening?`<p><strong>${esc(opening.reference)}</strong> · ${date(opening.recorded_at)} · ${esc(opening.actor.name)}</p><p class="notice ${data.opening_review_matches_published?'':'warning'}">${data.opening_review_matches_published?'يرتبط هذا الاعتماد بإصدار السياسات المنشور الحالي. يبقى التحقق الميداني مسؤولية التشغيل.':'هذا اعتماد تاريخي لإصدار سياسات سابق؛ أغلق الاستقبال وانشر النسخة الجديدة ثم سجل اعتماد فتح جديد.'}</p>`:'<p class="notice warning">لا يوجد اعتماد فتح مسجل. لا تعتبر إعدادات المتجر قبولًا تشغيليًا حتى يسجل المسؤول المرجع والمراجعات الخمس عند الفتح.</p>'}</section>
 <form id="store-draft" class="panel stack"><fieldset class="store-draft-fields stack"><h2>بيانات المنشأة والسياسات</h2><div class="two-col">${fields.map(([k,label])=>`<label class="field">${label}<input name="${k}" maxlength="500" value="${esc(p[k]||'')}" ${k==='email'?'type="email"':''}></label>`).join('')}${selectField('registration_type','نوع وثيقة المنشأة',[['','اختر'],['commercial_registration','سجل تجاري'],['freelance_document','وثيقة عمل حر'],['other_license','ترخيص آخر']],p.registration_type||'',{required:false})}${selectField('tax_status','الحالة الضريبية',[['','لم تُحدد'],['not_registered','غير مسجل في ضريبة القيمة المضافة'],['registered','مسجل في ضريبة القيمة المضافة']],p.tax_status||'',{required:false})}</div>${policies.map(([k,label])=>`<label class="field">${label}<textarea name="${k}" rows="7" maxlength="6000">${esc(p[k]||'')}</textarea></label>`).join('')}<p>أدخل السياسات الفعلية المعتمدة للمنشأة. الحد من 50 إلى 6000 حرف لكل سياسة عند النشر. تظهر النصوص كما تُكتب للعملاء.</p><button class="btn primary" type="submit">حفظ المسودة</button></fieldset></form>
 <section class="panel stack"><h2>نشر المسودة المحفوظة</h2><p>كل نشر ينشئ إصدارًا جديدًا. تظل شروط الطلبات السابقة مرتبطة بإصدارها الأصلي.</p><label class="check"><input type="checkbox" id="store-publish-confirm">راجعت البيانات والسياسات المحفوظة وأعتمد عرضها للعملاء</label><button class="btn primary" id="store-publish">نشر إصدار جديد</button></section>
 <form id="store-intake" class="panel stack"><h2>استقبال الطلبات</h2>${selectField('accepting_orders','الحالة المطلوبة',[['false','إيقاف الطلبات الجديدة'],['true','فتح الطلبات الجديدة']],String(data.accepting_orders))}${field('message','الرسالة الظاهرة للعملاء',{value:data.message})}${field('reason','سبب هذا التغيير')}${field('reference','مرجع اعتماد التشغيل (مطلوب للفتح)',{required:false})}<p>المراجعات التالية إقرار من مسؤول التشغيل؛ لا تغني عن فحص البضاعة أو اعتماد المستندات الفعلية.</p>${reviewed.map(([k,label])=>`<label class="check"><input type="checkbox" name="${k}">${label}</label>`).join('')}<button class="btn primary" type="submit">تطبيق حالة استقبال الطلبات</button></form></div>`);
 $('#store-draft').oninput=()=>{state.storefrontDirty=true;$('#store-publish').disabled=true;$('#store-publish-confirm').checked=false;$('#store-publish').textContent='احفظ التغييرات قبل النشر'};
 const current=()=>state.user===user&&state.page==='storefront'&&state.storefrontGeneration===generation;
 $('#store-draft').onsubmit=e=>{e.preventDefault();const form=e.target,fields=$('fieldset',form),profile=formData(form);busy($('button[type=submit]',form),async()=>{fields.disabled=true;try{await post('/api/ops/storefront/draft',{revision:data.revision,profile});if(!current())return;state.storefrontDirty=false;toast('حُفظت المسودة');await storefrontPage()}finally{fields.disabled=false}}).catch(()=>{})};
 $('#store-publish').onclick=()=>busy($('#store-publish'),async()=>{if(!$('#store-publish-confirm').checked)throw Error('راجع المسودة المحفوظة ثم حدّد موافقتك على النشر');await post('/api/ops/storefront/publish',{revision:data.revision,confirmed:true});if(!current())return;toast('نُشر إصدار جديد من بيانات المتجر والسياسات');await storefrontPage()}).catch(()=>{});
 $('#store-intake').onsubmit=e=>{e.preventDefault();busy($('button[type=submit]',e.target),async()=>{const f=formData(e.target),opening=f.accepting_orders==='true';await post('/api/ops/storefront/intake',{revision:data.revision,accepting_orders:opening,message:f.message,reason:f.reason,...(opening?{reference:f.reference,reviewed:Object.fromEntries(reviewed.map(([k])=>[k,f[k]==='on']))}:{})});if(!current())return;toast('تم تحديث استقبال الطلبات');await storefrontPage()}).catch(()=>{})};
}

function openingReview(data){
 const r=data?.last_opening_review,a=r?.actor,v=r?.reviewed;
 if(!r||!Number.isSafeInteger(r.recorded_at)||r.recorded_at<=0||typeof r.reference!=='string'||r.reference.length<5||r.reference.length>180||!a||typeof a.name!=='string'||!a.name.trim()||!v)return null;
 if(!['catalog','inventory','coverage','tax','operations'].every(k=>v[k]===true)||Object.keys(v).length!==5)return null;
 return r;
}

function launchChecks(data,health){
 const r=data?.readiness||{},count=n=>Number.isSafeInteger(n)&&n>=0,boolean=n=>typeof n==='boolean';
 const observation=operationalData(health),jobsKnown=!!observation&&boolean(health?.ok);
 const productsKnown=count(r.active_products)&&count(r.preview_products)&&count(r.available_products);
 return [
  {id:'merchant',title:'بيانات المنشأة والسياسات',page:'storefront',action:'إكمال بيانات المتجر',state:!boolean(r.profile_published)?'unknown':r.profile_published?'observed':'attention',detail:!boolean(r.profile_published)?'لم تصل حالة النشر. أعد تحديث الفحص.':r.profile_published?'يوجد إصدار منشور. راجع أنه يمثل المنشأة والسياسات المعتمدة.':'أدخل بيانات المنشأة والسياسات الفعلية، واحفظ المسودة ثم انشرها بعد مراجعتها.'},
  {id:'catalog',title:'المنتجات والأسعار والصور',page:'catalog',action:'مراجعة المنتجات',state:!productsKnown?'unknown':r.preview_products>0||r.active_products===0||r.available_products===0?'attention':'observed',detail:!productsKnown?'تعذر قراءة حالة المنتجات.':`منتجات نشطة: ${number(r.active_products)} · منتجات معاينة نشطة: ${number(r.preview_products)} · متوفرة للطلب: ${number(r.available_products)}. راجع الأسماء والأسعار والصور وأوقف منتجات المعاينة قبل البيع.`},
  {id:'supplier-sites',title:'الموردون ونقاط الاستلام',page:'pickup-sites',action:'تجهيز دليل الموردين',state:'review',detail:'سجّل الموردين والمحلات وعناوين الاستلام الحقيقية. لا يلزم مستودع أو رصيد مخزن؛ تسجيل الموقع لا يؤكد توفر البضاعة.'},
  {id:'procurement',title:'تحويل رحلة الطلب إلى الشراء المباشر',page:'pickup-sites',action:'مراجعة حدود المسار الجديد',state:'attention',detail:'قيد التنفيذ الهندسي: الطلب والتكليف والشراء والاستلام والبدائل ثم التوصيل، دون حجز مخزون مستودع. الدليل وحده لا يكمل التحويل؛ أبقِ استقبال الطلبات مغلقًا ولا تنشئ أرصدة وهمية.'},
  {id:'delivery',title:'مناطق ومواعيد التوصيل',page:'logistics',action:'إعداد التوصيل',state:!count(r.available_slots)?'unknown':r.available_slots>0?'observed':'attention',detail:!count(r.available_slots)?'تعذر قراءة المواعيد المتاحة.':`مواعيد متاحة مسجلة: ${number(r.available_slots)}. اعتمد التغطية الفعلية والرسوم والسعة مع فريق التوصيل.`},
  {id:'team',title:'الموظفون والتحصيل والدعم',page:'staff',action:'إعداد حسابات الفريق',state:'review',detail:'جهّز حساب كل موظف بدوره الصحيح، وراجع تنفيذ الطلب والتسليم وتحصيل النقد وتسوية العهد والاسترداد والدعم.'},
  {id:'tax',title:'الحالة الضريبية والفوترة',page:'storefront',action:'مراجعة الحالة الضريبية',state:!boolean(r.tax_supported)?'unknown':r.tax_supported?'observed':'attention',detail:!boolean(r.tax_supported)?'تعذر قراءة الحالة المسجلة.':r.tax_supported?'الحالة المنشورة مدعومة في الإعداد الحالي. يراجع المالك صحتها ومتطلبات الفوترة الفعلية.':'أدخل الحالة الفعلية للمنشأة. فتح البيع للمنشأة المسجلة ضريبيًا ينتظر اكتمال ربط الضرائب والفوترة.'},
  {id:'operations',title:'سلامة التشغيل',page:'health',action:'مراجعة تنبيهات التشغيل',state:!jobsKnown?'unknown':health.ok&&observation.ok?'observed':'attention',detail:!jobsKnown?'لم يصل فحص تشغيل مكتمل. أعد المحاولة قبل اعتماد التشغيل.':health.ok&&observation.ok?'فحص الأرصدة والمهام المجدولة سليم وقت هذه القراءة. يلزم أيضًا اعتماد التنبيهات الخارجية والنسخ الاحتياطي والتعافي الفعلي.':'ظهر تنبيه في الأرصدة أو المهام المجدولة. راجع التفاصيل وسبب التنبيه قبل اعتماد التشغيل.'}
 ];
}
function launchReport(data,health,checks=launchChecks(data,health)){
 const revision=Number.isSafeInteger(data?.revision)&&data.revision>=0?data.revision:null;
 const intake=revision!==null&&typeof data?.accepting_orders==='boolean'?(data.accepting_orders?'open':'closed'):'unknown';
 const policyVersion=Number.isSafeInteger(data?.published?.version)&&data.published.version>=1?data.published.version:null;
 const operations=operationalData(health),healthKnown=!!operations&&typeof health?.ok==='boolean',opening=openingReview(data);
 return {
  schema:'jana-launch-observation/v1',
  admission:{state:intake,storefront_revision:revision,published_policy_version:policyVersion,opening_review:opening?{recorded_at:opening.recorded_at,matches_published_policy:data.opening_review_matches_published===true}:null},
  checks:checks.map(c=>({id:c.id,title:c.title,state:c.state,action:c.action,action_url:'/admin.html#'+c.page})),
  operations:healthKnown?{ok:health.ok&&operations.ok===true,checked_at:Number.isSafeInteger(operations.checked_at)?operations.checked_at:null,alert_count:Number.isSafeInteger(operations.alert_count)&&operations.alert_count>=0?operations.alert_count:null}:null,
  manual_acceptance_required:true,
  notice:'هذا تقرير حالات مسجلة وروابط متابعة، وليس اعتمادًا تجاريًا أو بديلًا عن مراجعة المنشأة والبضاعة والفريق والأجهزة.'
 };
}
function launchReportHref(data,health,checks){return 'data:application/json;charset=utf-8,'+encodeURIComponent(JSON.stringify(launchReport(data,health,checks),null,2))}
async function launchPage(){
 const user=state.user,generation=++state.launchGeneration;
 if(user?.role!=='admin')throw Error('مركز إعداد الإطلاق متاح للمدير فقط');
 shell('<section class="panel" role="status" data-launch-loading>جار قراءة حالة المتجر وخطوات الإعداد…</section>');
 const reads=await Promise.allSettled([get('/api/ops/storefront'),get('/api/ops/deep-health')]);
 if(state.user!==user||state.page!=='launch'||state.launchGeneration!==generation)return;
 if(reads.some(r=>r.status==='rejected'&&r.reason?.code==='AUTH_REQUIRED')){state.user=null;state.storefrontDirty=false;clearOrderPages();login();return}
 const data=reads[0].status==='fulfilled'?reads[0].value:null,health=reads[1].status==='fulfilled'?reads[1].value:null;
 const known=Number.isSafeInteger(data?.revision)&&data.revision>=0&&typeof data?.accepting_orders==='boolean';
 const intake=known?(data.accepting_orders?'open':'closed'):'unknown',checks=launchChecks(data,health),reportHref=launchReportHref(data,health,checks),opening=openingReview(data);
 const labels={observed:'بيانات مسجلة',attention:'تحتاج إكمالًا',review:'مراجعة فعلية',unknown:'غير مؤكد'};
 shell(`<div class="stack" data-launch-center><section class="panel stack launch-status" data-launch-state="${intake}" role="status"><h2>${intake==='open'?'استقبال الطلبات مفتوح':intake==='closed'?'استقبال الطلبات متوقف':'تعذر تأكيد حالة استقبال الطلبات'}</h2><p>هذه الصفحة تجمع الإعدادات والفحوص المسجلة. المراجعة الفعلية للمنشأة والبضاعة والفريق تقع على مسؤول التشغيل؛ لا يُستنتج اكتمالها من الاختبارات البرمجية.</p>${known?`<p>مراجعة إعدادات المتجر: ${number(data.revision)}${Number.isSafeInteger(data.published?.version)?' · إصدار السياسات المنشور: '+number(data.published.version):''}</p>`:'<p class="notice warning">تعذر تحميل إعدادات المتجر. حدّث الصفحة؛ لن نعرض حالة فتح أو إغلاق مفترضة.</p>'}${opening?`<p data-launch-opening-review="${data.opening_review_matches_published?'current':'historical'}">آخر اعتماد فتح: ${date(opening.recorded_at)} · ${esc(opening.actor.name)} · ${esc(opening.reference)}${data.opening_review_matches_published?'':' · لإصدار سياسات سابق'}</p>`:'<p data-launch-opening-review="none">لا يوجد اعتماد فتح مسجل حتى الآن.</p>'}<div class="ops-actions"><a class="btn primary" href="/admin.html#storefront">مراجعة إعدادات استقبال الطلبات</a><a class="btn outline" href="/start.html">روابط المتجر والفريق</a><a class="btn outline" href="/">معاينة متجر العملاء</a><a class="btn outline" data-launch-download download="jana-launch-readiness.json" href="${esc(reportHref)}">تنزيل تقرير حالة الإطلاق</a></div><p class="muted">التقرير لا يتضمن مرجع الاعتماد أو اسم الموظف أو نصوص السياسات أو بيانات التواصل، ولا يغيّر أي إعداد.</p></section>
 <section class="stack"><h2>أكمل خطوات الإطلاق</h2><div class="launch-grid">${checks.map((c,i)=>`<article class="panel stack launch-step" data-launch-check="${c.id}" data-launch-check-state="${c.state}"><div class="row between wrap"><h3>${number(i+1)}. ${c.title}</h3><span class="badge ${c.state==='observed'?'success':c.state==='review'?'neutral':'danger'}">${labels[c.state]}</span></div><p>${c.detail}</p><a class="btn outline" href="/admin.html#${c.page}">${c.action}</a></article>`).join('')}</div></section>
 <section class="panel stack"><h2>اعتمادات قبل تسليم التشغيل</h2><ul class="launch-review-list"><li>اعتماد بيانات المنشأة والمنتجات والأسعار والصور والموردين ومناطق التوصيل الفعلية بعد اكتمال تحويل رحلة الطلب.</li><li>تجربة تشغيل معتمدة للفريق على أجهزة فعلية، مع التحصيل والتسويات والاسترداد وخدمة العملاء.</li><li>تجهيز استعادة الحساب ومزودي الخدمات وقناة التنبيهات، وإثبات النسخ الاحتياطي والتعافي في بيئة مستقلة.</li><li>اعتماد حسابات وتوقيع ونشر تطبيقات المتاجر. نسخة المتصفح متاحة للجوال؛ نجاح بناء التطبيق لا يعني نشره في Apple أو Google.</li></ul><p class="notice">بعد إكمال المراجعة افتح «إعدادات المتجر» وسجل اعتماد التشغيل ثم طبّق حالة استقبال الطلبات. فتح هذه الصفحة أو زيارة الروابط لا يغيّر الأسعار أو المخزون ولا يفتح البيع.</p></section></div>`);
}
